/// Helper: create a workflow via FoundryStore and return its id.
fn setup_test_workflow(store: &FoundryStore) -> String {
    use foundry_core::graph;
    use foundry_core::intent;
    let workflow = graph::create_workflow(intent::parse_intent("Test workflow for patch apply"));
    store.save_workflow(&workflow).unwrap();
    workflow.id
}

fn foundry() -> Command {
    Command::cargo_bin("foundry").expect("foundry binary should build")
}

fn persist_executor_state(
    store_path: &Path,
    id: &str,
    installed: bool,
    configured: bool,
    allowed: bool,
    non_interactive_ready: bool,
) {
    let canonical_id = foundry_core::executor::canonical_executor_id(id);
    let command = if canonical_id == "agy" {
        "agy".to_string()
    } else {
        canonical_id.clone()
    };
    let store = FoundryStore::open(store_path).unwrap();
    store
        .save_executor_state(
            &canonical_id,
            &serde_json::json!({
                "id": canonical_id.clone(),
                "display_name": format!("{id} test executor"),
                "command": command.clone(),
                "installed": installed,
                "configured": configured,
                "command_path": installed.then(|| format!("/tmp/{command}")),
                "config_evidence": configured.then_some("test configuration").into_iter().collect::<Vec<_>>(),
                "non_interactive_ready": non_interactive_ready,
                "probe_evidence": ["test readiness"],
                "foundry_first_ready": false,
                "foundry_first_entrypoint": null,
                "harness_status": null,
                "allowed": allowed,
                "decision_source": if allowed { "human_allow" } else { "human_deny" },
                "synced_at": "2026-07-29T00:00:00Z"
            }),
        )
        .unwrap();
}

fn persist_ready_executor_state(store_path: &Path, id: &str) {
    persist_executor_state(store_path, id, true, true, true, true);
}

fn persist_fresh_executor_quota(store: &FoundryStore, id: &str) {
    let executor = foundry_core::executor::canonical_executor_id(id);
    let provider = if executor == "codex" {
        "openai"
    } else {
        "configured_cli"
    };
    store
        .save_executor_quota(
            &executor,
            provider,
            "test",
            &serde_json::json!({
                "executor": executor,
                "provider": provider,
                "model": "test",
                "local_vs_non_local": "non_local",
                "free_vs_paid_if_known": "unknown",
                "remaining_quota": "available",
                "rate_limit_risk": "low",
                "monetary_or_token_cost": "unknown",
                "latency": "test",
                "expected_quality": "test",
                "suitability": "test",
                "source": "foundry_cli_contract_fixture",
                "observed_at": chrono::Utc::now().to_rfc3339(),
            }),
        )
        .unwrap();
}

fn register_task_scoped_test_worktree(
    store: &FoundryStore,
    workspace_root: &Path,
    workflow_id: &str,
    task_id: &str,
) -> std::path::PathBuf {
    use foundry_core::worktree::{
        bound_worktree_mutation_claim, register_worktree, WorktreeRegisterOptions,
    };

    if let Some(claim) = bound_worktree_mutation_claim(store, workflow_id, task_id).unwrap() {
        assert_eq!(claim.binding_scope, "task");
        return std::path::PathBuf::from(claim.worktree_root);
    }

    let safe_task_id = task_id
        .chars()
        .map(|character| {
            if character.is_ascii_alphanumeric() || matches!(character, '-' | '_' | '.') {
                character
            } else {
                '-'
            }
        })
        .collect::<String>();
    let repository = workspace_root
        .join("task-scoped-worktrees")
        .join(&safe_task_id);
    fs::create_dir_all(&repository).unwrap();
    assert!(StdCommand::new("git")
        .args(["init", "--quiet"])
        .current_dir(&repository)
        .status()
        .expect("git init should run")
        .success());
    configure_test_git_identity(&repository);
    fs::write(
        repository.join("README.md"),
        format!("# Isolated fixture for {task_id}\n"),
    )
    .unwrap();
    assert!(StdCommand::new("git")
        .args(["add", "README.md"])
        .current_dir(&repository)
        .status()
        .expect("git add should run")
        .success());
    assert!(StdCommand::new("git")
        .args(["commit", "--quiet", "-m", "test fixture"])
        .current_dir(&repository)
        .status()
        .expect("git commit should run")
        .success());

    let worktree_id = format!(
        "wt-{}",
        &hex_sha256(format!("{workflow_id}:{task_id}").as_bytes())[..16]
    );
    let report = register_worktree(
        store,
        WorktreeRegisterOptions {
            path: repository.clone(),
            id: Some(worktree_id),
            workflow_id: Some(workflow_id.to_string()),
            task_id: Some(task_id.to_string()),
            origin: "foundry_cli_contract_fixture".to_string(),
            created_by_foundry: false,
        },
    )
    .unwrap();
    assert_eq!(
        report
            .binding
            .as_ref()
            .and_then(|binding| binding.task_id.as_deref()),
        Some(task_id)
    );
    let claim = bound_worktree_mutation_claim(store, workflow_id, task_id)
        .unwrap()
        .expect("task-scoped worktree claim should exist");
    assert_eq!(claim.binding_scope, "task");
    assert_eq!(
        fs::canonicalize(&repository).unwrap(),
        fs::canonicalize(claim.worktree_root).unwrap()
    );
    repository
}

fn materialize_and_bind_final_audit_task(
    store_path: &Path,
    workspace_root: &Path,
    run_id: &str,
    workflow_id: &str,
) -> String {
    let blocked = foundry()
        .args([
            "--store",
            store_path.to_str().unwrap(),
            "request",
            "drive",
            "--run",
            run_id,
            "--executor",
            "codex",
            "--ttl-seconds",
            "300",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let blocked: Value = serde_json::from_slice(&blocked).unwrap();
    assert_eq!(blocked["status"], "dispatch_blocked");
    let deferred = blocked["dispatch_frontier"]["wave"]["deferred"]
        .as_array()
        .expect("blocked audit dispatch should expose deferred work");
    let audit = deferred
        .iter()
        .find(|task| task["title"] == "Audit final completion criteria")
        .expect("final audit task should be materialized before worktree provisioning");
    assert_eq!(audit["status"], "deferred_task_worktree_required");
    let audit_task_id = audit["task_id"].as_str().unwrap().to_string();

    let store = FoundryStore::open(store_path).unwrap();
    register_task_scoped_test_worktree(&store, workspace_root, workflow_id, &audit_task_id);
    audit_task_id
}

fn drive_request_with_ready_host_snapshot(store_path: &Path, run_id: &str) -> Value {
    let output = foundry()
        .env(
            "FOUNDRY_TEST_HOST_RESOURCE_SNAPSHOT_JSON",
            serde_json::json!({
                "cpu_count": 8,
                "load_one": 0.25,
                "memory_available_bytes": 8_u64 * 1024 * 1024 * 1024,
                "swap_free_bytes": 1024_u64 * 1024 * 1024,
                "disk_free_bytes": 100_u64 * 1024 * 1024 * 1024,
                "disk_total_bytes": 200_u64 * 1024 * 1024 * 1024,
            })
            .to_string(),
        )
        .args([
            "--store",
            store_path.to_str().unwrap(),
            "request",
            "drive",
            "--run",
            run_id,
            "--executor",
            "codex",
            "--ttl-seconds",
            "300",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    serde_json::from_slice(&output).unwrap()
}

fn configure_test_git_identity(repo: &Path) {
    for (key, value) in [
        ("user.email", "test@example.com"),
        ("user.name", "Foundry Test"),
    ] {
        assert!(StdCommand::new("git")
            .args(["config", key, value])
            .current_dir(repo)
            .status()
            .expect("git config should run")
            .success());
    }
}

fn foundry_tui_test_guard() -> MutexGuard<'static, ()> {
    static LOCK: OnceLock<Mutex<()>> = OnceLock::new();
    LOCK.get_or_init(|| Mutex::new(()))
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
}

fn assert_foundry_store_prefix(command: &Value, store: &Path) {
    assert!(store.is_absolute(), "test store path must be absolute");
    let command = command.as_array().expect("command must be an array");
    assert!(
        command.len() >= 3,
        "command must include the Foundry store prefix"
    );
    assert_eq!(command[0], "foundry");
    assert_eq!(command[1], "--store");
    assert_eq!(command[2], store.display().to_string());
}

fn attach_milestone_receipt(
    store: &Path,
    artifact_root: &Path,
    capability: &str,
    kind: &str,
    payload: Value,
) {
    let receipt = artifact_root.join(format!("{capability}-{kind}.json"));
    fs::write(&receipt, serde_json::to_vec_pretty(&payload).unwrap()).unwrap();
    // The retired 0.5 selector remains a read-only compatibility alias for
    // evidence that is stored under the canonical 0.6 milestone.
    foundry()
        .arg("--store")
        .arg(store.to_str().unwrap())
        .args([
            "milestone",
            "attach-evidence",
            "--version",
            "0.5",
            "--capability",
            capability,
            "--kind",
            kind,
            "--summary",
            "Operator-approved required milestone receipt.",
            "--artifact",
        ])
        .arg(receipt.to_str().unwrap())
        .args([
            "--approved-by",
            "arthur",
            "--origin",
            "codex",
            "--output",
            "json",
        ])
        .assert()
        .success();
}

