fn sqlite_table_columns(connection: &Connection, table: &str) -> Vec<String> {
    let mut statement = connection
        .prepare(&format!("PRAGMA table_info({table})"))
        .unwrap();
    let rows = statement
        .query_map([], |row| row.get::<_, String>(1))
        .unwrap();
    rows.map(|row| row.unwrap()).collect()
}

fn sqlite_index_names(connection: &Connection, table: &str) -> Vec<String> {
    let mut statement = connection
        .prepare(&format!("PRAGMA index_list({table})"))
        .unwrap();
    let rows = statement
        .query_map([], |row| row.get::<_, String>(1))
        .unwrap();
    rows.map(|row| row.unwrap()).collect()
}

#[test]
fn harness_token_headroom_compresses_logs_and_mcp_wrap_plan_shapes_cli_environment() {
    let content = (0..80)
        .map(|index| format!("line {index}: error: failed to process request {index}"))
        .collect::<Vec<_>>()
        .join("\n");
    let output = foundry()
        .args([
            "harness",
            "token-headroom",
            "--content",
            &content,
            "--kind",
            "log",
            "--budget-tokens",
            "120",
            "--source",
            "test",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let json: Value = serde_json::from_slice(&output).unwrap();
    assert_eq!(json["schema_version"], "foundry.harness.token_headroom.v1");
    assert_eq!(json["content_kind"], "log");
    assert_eq!(json["strategy"], "signal_log_compressor");
    assert!(json["estimated_saved_tokens"].as_u64().unwrap() > 0);
    assert!(json["retrieval_ref"]
        .as_str()
        .unwrap()
        .starts_with("foundry://harness/headroom/"));

    let temp = tempdir().unwrap();
    let store = temp.path().join("foundry.sqlite");
    let persisted_output = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "harness",
            "token-headroom",
            "--content",
            &content,
            "--kind",
            "log",
            "--budget-tokens",
            "120",
            "--source",
            "persisted-test",
            "--persist",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let persisted: Value = serde_json::from_slice(&persisted_output).unwrap();
    assert_eq!(persisted["persisted"], true);
    assert_eq!(persisted["retrieval_available"], true);
    assert_eq!(persisted["store_status"], "stored_local_sqlite");
    let retrieval_ref = persisted["retrieval_ref"].as_str().unwrap();
    let retrieval_output = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "harness",
            "retrieve-headroom",
            "--ref",
            retrieval_ref,
            "--include-content",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let retrieval: Value = serde_json::from_slice(&retrieval_output).unwrap();
    assert_eq!(
        retrieval["schema_version"],
        "foundry.harness.headroom_retrieval.v1"
    );
    assert_eq!(retrieval["status"], "headroom_blob_retrieved");
    assert_eq!(retrieval["found"], true);
    assert_eq!(retrieval["source"], "persisted-test");
    assert_eq!(retrieval["original_content"], content);
    assert_eq!(
        retrieval["compressed_sha256"],
        persisted["compressed_sha256"]
    );

    let mcp_headroom_input = serde_json::json!({
        "content": "alpha\nbeta\nwarning: check this\nomega",
        "kind": "log",
        "budget_tokens": 12,
        "source": "mcp-persisted-test",
        "persist": true
    });
    let mcp_headroom_output = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "mcp",
            "call",
            "foundry.harness.token_headroom",
            "--input",
            &mcp_headroom_input.to_string(),
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let mcp_headroom: Value = serde_json::from_slice(&mcp_headroom_output).unwrap();
    assert_eq!(mcp_headroom["result"]["persisted"], true);
    let mcp_retrieval_input = serde_json::json!({
        "retrieval_ref": mcp_headroom["result"]["retrieval_ref"],
        "include_content": true
    });
    let mcp_retrieval_output = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "mcp",
            "call",
            "foundry.harness.retrieve_headroom",
            "--input",
            &mcp_retrieval_input.to_string(),
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let mcp_retrieval: Value = serde_json::from_slice(&mcp_retrieval_output).unwrap();
    assert_eq!(
        mcp_retrieval["result"]["schema_version"],
        "foundry.harness.headroom_retrieval.v1"
    );
    assert_eq!(mcp_retrieval["result"]["found"], true);
    assert_eq!(mcp_retrieval["result"]["source"], "mcp-persisted-test");
    assert_eq!(
        mcp_retrieval["result"]["original_content"],
        "alpha\nbeta\nwarning: check this\nomega"
    );

    let mcp_input = serde_json::json!({
        "executor": "claude-code",
        "command": ["claude", "--model", "sonnet"],
        "foundry_first": true,
        "workflow_id": "wf_demo",
        "task_id": "task_demo",
        "run_id": "run_demo",
        "context_budget": 2048,
        "token_headroom": true
    });
    let mcp_output = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "mcp",
            "call",
            "foundry.harness.wrap_plan",
            "--input",
            &mcp_input.to_string(),
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let mcp_json: Value = serde_json::from_slice(&mcp_output).unwrap();
    assert_eq!(mcp_json["schema_version"], "foundry.mcp.call.v1");
    assert_eq!(
        mcp_json["result"]["schema_version"],
        "foundry.harness.cli_wrapper_plan.v1"
    );
    assert_eq!(
        mcp_json["result"]["orchestration_contract"]["schema_version"],
        "foundry.harness.orchestration_contract.v1"
    );
    assert_eq!(
        mcp_json["result"]["headroom_runtime_plan"]["schema_version"],
        "foundry.harness.headroom_runtime_plan.v1"
    );
    assert_eq!(mcp_json["result"]["headroom_runtime_plan"]["enabled"], true);
    assert!(
        mcp_json["result"]["headroom_runtime_plan"]["interception_points"]
            .as_array()
            .unwrap()
            .iter()
            .any(|point| point["point_id"] == "tool_output"
                && point["action"] == "compress_then_return_retrieval_ref")
    );
    assert!(
        mcp_json["result"]["headroom_runtime_plan"]["content_routes"]
            .as_array()
            .unwrap()
            .iter()
            .any(|route| route["content_kind"] == "log"
                && route["strategy"] == "signal_log_compressor"
                && route["reversible"] == true)
    );
    assert_eq!(
        mcp_json["result"]["headroom_runtime_plan"]["reversible_store"]["uri_scheme"],
        "foundry://harness/headroom/"
    );
    assert!(mcp_json["result"]["headroom_runtime_plan"]["mcp_tools"]
        .as_array()
        .unwrap()
        .contains(&serde_json::json!("foundry.harness.retrieve_headroom")));
    assert!(mcp_json["result"]["env"]
        .as_array()
        .unwrap()
        .iter()
        .any(|item| item["name"] == "FOUNDRY_HEADROOM_RUNTIME_PLAN"
            && item["value"] == "foundry.harness.headroom_runtime_plan.v1"));
    assert!(
        mcp_json["result"]["orchestration_contract"]["routing_stages"]
            .as_array()
            .unwrap()
            .iter()
            .any(|item| item["id"] == "mcp_router" && item["owner"] == "foundry")
    );
    assert_eq!(mcp_json["result"]["executor"], "claude");
    assert_eq!(mcp_json["result"]["foundry_first"], true);
    assert!(mcp_json["result"]["launch_command"]
        .as_array()
        .unwrap()
        .contains(&Value::String("--foundry-first".to_string())));
    let env = mcp_json["result"]["env"].as_array().unwrap();
    assert!(env
        .iter()
        .any(|item| item["name"] == "ENABLE_TOOL_SEARCH" && item["value"] == "true"));
    assert!(env
        .iter()
        .any(|item| item["name"] == "FOUNDRY_WORKFLOW_ID" && item["value"] == "wf_demo"));
    assert!(env
        .iter()
        .any(|item| item["name"] == "FOUNDRY_TASK_ID" && item["value"] == "task_demo"));
    assert!(env
        .iter()
        .any(|item| item["name"] == "FOUNDRY_TOKEN_HEADROOM" && item["value"] == "enabled"));
    assert!(mcp_json["result"]["launch_command"]
        .as_array()
        .unwrap()
        .windows(2)
        .any(|pair| pair[0] == "--task" && pair[1] == "task_demo"));

    let exec_output = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "harness",
            "exec",
            "--executor",
            "codex",
            "--foundry-first",
            "--workflow",
            "wf_demo",
            "--task",
            "task_demo",
            "--run",
            "run_demo",
            "--context-budget",
            "2048",
            "--",
            "definitely-not-a-real-foundry-test-cli",
            "--version",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let exec_json: Value = serde_json::from_slice(&exec_output).unwrap();
    assert_eq!(
        exec_json["schema_version"],
        "foundry.harness.exec_receipt.v1"
    );
    assert_eq!(exec_json["status"], "harness_exec_dry_run");
    assert_eq!(exec_json["executor"], "codex");
    assert_eq!(exec_json["task_id"], "task_demo");
    assert_eq!(exec_json["dry_run"], true);
    assert_eq!(exec_json["allow_exec"], false);
    assert_eq!(exec_json["executed"], false);
    assert_eq!(exec_json["resolution_status"], "executable_missing");
    assert_eq!(
        exec_json["runtime_security_guardrails"]["schema_version"],
        "foundry.runtime.security_guardrails.v1"
    );
    assert_eq!(
        exec_json["runtime_security_guardrails"]["enforcement_owner"],
        "foundry_runtime"
    );
    assert_eq!(
        exec_json["runtime_security_guardrails"]["coverage_scope"],
        "workflow_agent_cli_mcp_deterministic_process"
    );
    assert_eq!(
        exec_json["runtime_security_guardrails"]["guardrails"]
            .as_array()
            .unwrap()
            .len(),
        10
    );
    for guardrail_id in [
        "filesystem_permissions",
        "command_execution_permissions",
        "network_permissions",
        "credential_secret_permissions",
        "tool_usage_permissions",
        "resource_consumption_limits",
        "human_approval_gates",
        "tenant_project_isolation",
        "audit_traceability",
        "organizational_policy_engine",
    ] {
        assert!(
            exec_json["runtime_security_guardrails"]["guardrails"]
                .as_array()
                .unwrap()
                .iter()
                .any(|guardrail| guardrail["id"] == guardrail_id
                    && guardrail["native_runtime_capability"] == true),
            "missing native runtime guardrail {guardrail_id}"
        );
    }
    assert_eq!(
        exec_json["wrapper_plan"]["schema_version"],
        "foundry.harness.cli_wrapper_plan.v1"
    );
    assert_eq!(
        exec_json["wrapper_plan"]["orchestration_contract"]["control_plane"],
        "foundry_core"
    );
    let exec_env = exec_json["wrapper_plan"]["env"].as_array().unwrap();
    assert!(exec_env
        .iter()
        .any(|item| item["name"] == "FOUNDRY_RUN_ID" && item["value"] == "run_demo"));
    assert!(exec_env
        .iter()
        .any(|item| item["name"] == "FOUNDRY_TASK_ID" && item["value"] == "task_demo"));

    let mcp_exec_input = serde_json::json!({
        "executor": "opencode",
        "command": ["definitely-not-a-real-foundry-test-cli", "--help"],
        "foundry_first": true,
        "workflow_id": "wf_demo",
        "task_id": "task_mcp_demo",
        "dry_run": true,
        "allow_exec": false
    });
    let mcp_exec_output = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "mcp",
            "call",
            "foundry.harness.exec",
            "--input",
            &mcp_exec_input.to_string(),
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let mcp_exec: Value = serde_json::from_slice(&mcp_exec_output).unwrap();
    assert_eq!(
        mcp_exec["result"]["schema_version"],
        "foundry.harness.exec_receipt.v1"
    );
    assert_eq!(mcp_exec["result"]["status"], "harness_exec_dry_run");
    assert_eq!(mcp_exec["result"]["executed"], false);
    assert_eq!(mcp_exec["result"]["task_id"], "task_mcp_demo");
    assert_eq!(mcp_exec["result"]["event_recorded"], true);
    assert!(mcp_exec["result"]["global_event_id"].as_i64().unwrap() > 0);
}

#[test]
fn harness_cli_honors_foundry_first_default_mode_with_explicit_observe_only_override() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("foundry.sqlite");

    let output = foundry()
        .env("FOUNDRY_HARNESS_DEFAULT_MODE", "foundry_first")
        .args([
            "harness",
            "wrap-plan",
            "--executor",
            "codex",
            "--cmd",
            "codex",
            "--workflow",
            "wf_default_harness",
            "--task",
            "task-default-harness",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let json: Value = serde_json::from_slice(&output).unwrap();
    assert_eq!(
        json["schema_version"],
        "foundry.harness.cli_wrapper_plan.v1"
    );
    assert_eq!(json["foundry_first"], true);
    assert_eq!(json["foundry_first_source"], "env_default");
    assert!(json["launch_command"]
        .as_array()
        .unwrap()
        .contains(&Value::String("--foundry-first".to_string())));
    let env = json["env"].as_array().unwrap();
    assert!(env
        .iter()
        .any(|item| item["name"] == "FOUNDRY_HARNESS_MODE" && item["value"] == "foundry_first"));
    assert!(env.iter().any(
        |item| item["name"] == "FOUNDRY_HARNESS_MODE_SOURCE" && item["value"] == "env_default"
    ));

    let observe_only_output = foundry()
        .env("FOUNDRY_HARNESS_DEFAULT_MODE", "foundry_first")
        .args([
            "harness",
            "wrap-plan",
            "--executor",
            "codex",
            "--cmd",
            "codex",
            "--observe-only",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let observe_only: Value = serde_json::from_slice(&observe_only_output).unwrap();
    assert_eq!(observe_only["foundry_first"], false);
    assert_eq!(observe_only["foundry_first_source"], "observe_only_flag");
    assert!(!observe_only["launch_command"]
        .as_array()
        .unwrap()
        .contains(&Value::String("--foundry-first".to_string())));

    let exec_output = foundry()
        .env("FOUNDRY_HARNESS_DEFAULT_MODE", "foundry_first")
        .args([
            "--store",
            store.to_str().unwrap(),
            "harness",
            "exec",
            "--executor",
            "opencode",
            "--workflow",
            "wf_default_harness",
            "--task",
            "task-default-harness",
            "--",
            "definitely-not-a-real-foundry-test-cli",
            "--version",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let exec_json: Value = serde_json::from_slice(&exec_output).unwrap();
    assert_eq!(
        exec_json["schema_version"],
        "foundry.harness.exec_receipt.v1"
    );
    assert_eq!(exec_json["foundry_first"], true);
    assert_eq!(exec_json["foundry_first_source"], "env_default");
    assert_eq!(exec_json["wrapper_plan"]["foundry_first"], true);
    assert_eq!(
        exec_json["wrapper_plan"]["foundry_first_source"],
        "env_default"
    );
    assert!(exec_json["wrapper_plan"]["launch_command"]
        .as_array()
        .unwrap()
        .contains(&Value::String("--foundry-first".to_string())));
}

