#[test]
fn milestone_status_surfaces_05_boundary_and_promotion_gate() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("foundry.sqlite");

    let output = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "milestone",
            "status",
            "--version",
            "0.5",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();

    let json: Value = serde_json::from_slice(&output).unwrap();
    assert_eq!(json["schema_version"], "foundry.milestone.status.v1");
    assert_eq!(json["milestone"], "0.6");
    assert_eq!(json["requested_milestone"], "0.5");
    assert_eq!(json["compatibility_mode"], "legacy_query_alias");
    assert_eq!(
        json["status_vocabulary"],
        serde_json::json!([
            "implemented",
            "validated",
            "groundwork",
            "planned",
            "blocked"
        ])
    );
    assert_eq!(json["promotion_decision"]["decision"], "promote");
    assert_eq!(json["promotion_decision"]["promotable"], true);
    let blocked_by = json["promotion_decision"]["blocked_by"].as_array().unwrap();
    assert!(blocked_by.is_empty());
    assert!(
        !blocked_by.contains(&serde_json::json!("creative_artifact_ir")),
        "creative_artifact_ir is now validated and should not block"
    );
    assert!(
        !blocked_by.contains(&serde_json::json!("export_demo_baseline")),
        "export_demo_baseline is now validated and should not block"
    );

    let capabilities = json["capabilities"].as_array().unwrap();
    let replacement_cli = capabilities
        .iter()
        .find(|capability| capability["id"] == "replacement_grade_cli")
        .unwrap();
    assert_eq!(replacement_cli["status"], "groundwork");
    assert_eq!(replacement_cli["required_for_promotion"], false);
    let multimodal = capabilities
        .iter()
        .find(|capability| capability["id"] == "experimental_multimodal_runtime")
        .unwrap();
    assert_eq!(multimodal["status"], "groundwork");
    assert_eq!(multimodal["required_for_promotion"], false);
    let scheduler = capabilities
        .iter()
        .find(|capability| capability["id"] == "scheduler_loop_subflow_foundation")
        .unwrap();
    assert_eq!(scheduler["status"], "validated");

    let creative_ir = capabilities
        .iter()
        .find(|capability| capability["id"] == "creative_artifact_ir")
        .unwrap();
    assert_eq!(creative_ir["status"], "validated");
    assert!(creative_ir["gap_before_promotion"]
        .as_str()
        .unwrap()
        .contains("0.6"));

    let replacement_cli = capabilities
        .iter()
        .find(|capability| capability["id"] == "replacement_grade_cli")
        .unwrap();
    assert_eq!(replacement_cli["status"], "groundwork");
    assert!(replacement_cli["evidence"]
        .as_str()
        .unwrap()
        .contains("foundry milestone cli-demo"));
    assert!(replacement_cli["evidence"]
        .as_str()
        .unwrap()
        .contains("require_lineage_for_exec"));
    assert!(replacement_cli["evidence"]
        .as_str()
        .unwrap()
        .contains("--project-root"));
    assert!(replacement_cli["evidence"]
        .as_str()
        .unwrap()
        .contains("wrap-plan --project-root"));
    assert!(replacement_cli["evidence"]
        .as_str()
        .unwrap()
        .contains("install-shims --project-root"));
    assert!(replacement_cli["evidence"]
        .as_str()
        .unwrap()
        .contains("patch_edit_intake"));
    assert!(replacement_cli["evidence"]
        .as_str()
        .unwrap()
        .contains("patch_lifecycle_demo"));
    assert!(replacement_cli["evidence"]
        .as_str()
        .unwrap()
        .contains("brain_handoff_demo"));
    assert!(replacement_cli["evidence"]
        .as_str()
        .unwrap()
        .contains("connected_external_brain_provider"));
    assert!(replacement_cli["evidence"]
        .as_str()
        .unwrap()
        .contains("exec --project-root"));
    assert!(replacement_cli["gap_before_promotion"]
        .as_str()
        .unwrap()
        .contains("file editing"));

    let multimodal = capabilities
        .iter()
        .find(|capability| capability["id"] == "experimental_multimodal_runtime")
        .unwrap();
    assert_eq!(multimodal["status"], "groundwork");
    assert!(multimodal["evidence"]
        .as_str()
        .unwrap()
        .contains("foundry multimodal benchmark-result"));
    assert!(multimodal["evidence"]
        .as_str()
        .unwrap()
        .contains("foundry multimodal runtime-benchmark"));
    assert!(multimodal["evidence"]
        .as_str()
        .unwrap()
        .contains(".foundry/multimodal.json"));
    assert!(multimodal["evidence"]
        .as_str()
        .unwrap()
        .contains(".foundry/multimodal-runtimes.json"));
    assert!(multimodal["evidence"]
        .as_str()
        .unwrap()
        .contains("connected_runtime"));
    assert!(multimodal["gap_before_promotion"]
        .as_str()
        .unwrap()
        .contains("production model/runtime benchmark"));

    assert_eq!(json["summary"]["validated"].as_u64().unwrap(), 9);
    assert_eq!(json["summary"]["groundwork"].as_u64().unwrap(), 2);
    assert_eq!(json["summary"]["planned"].as_u64().unwrap(), 0);
}

