#[test]
fn milestone_evidence_plan_blocks_missing_connected_brain_wrapper_command() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("foundry.sqlite");
    let project = temp.path().join("missing-wrapper-project");
    let foundry_dir = project.join(".foundry");
    fs::create_dir_all(&foundry_dir).unwrap();
    let missing_wrapper = temp.path().join("missing-provider-wrapper.sh");

    fs::write(
        foundry_dir.join("connected-brain-runtimes.json"),
        serde_json::to_string_pretty(&serde_json::json!({
            "providers": [{
                "id": "project-provider",
                "brain_id": "project-provider",
                "model_id": "project-provider-model-v1",
                "provider_class": "external_cli",
                "capabilities": ["replacement_grade_cli"],
                "command": [missing_wrapper.display().to_string()],
                "approved_by": "arthur",
                "approval_ref": "provider-approval-missing-wrapper-001",
                "allow_model_execution": true,
                "network_access": false,
                "device_access": false,
                "external_resources_mutated": false
            }]
        }))
        .unwrap(),
    )
    .unwrap();

    let output = foundry()
        .arg("--store")
        .arg(store.to_str().unwrap())
        .args([
            "milestone",
            "evidence-plan",
            "--version",
            "0.5",
            "--capability",
            "replacement_grade_cli",
            "--project-root",
        ])
        .arg(project.to_str().unwrap())
        .args(["--connected-brain", "project-provider", "--output", "json"])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let json: Value = serde_json::from_slice(&output).unwrap();
    assert_eq!(json["status"], "blocked_project_evidence_inputs");
    assert_eq!(json["ready_to_collect_evidence"], false);
    assert!(json["config_checks"]
        .as_array()
        .unwrap()
        .iter()
        .any(|check| check["id"] == "connected_brain_provider"
            && check["status"] == "ready"
            && check["selected_id"] == "project-provider"));
    let command_check = json["config_checks"]
        .as_array()
        .unwrap()
        .iter()
        .find(|check| check["id"] == "connected_brain_provider_command")
        .expect("evidence-plan should statically audit connected brain wrapper command");
    assert_eq!(command_check["status"], "blocked");
    assert_eq!(command_check["selected_id"], "project-provider");
    assert_eq!(command_check["path"], missing_wrapper.display().to_string());
    assert!(command_check["summary"]
        .as_str()
        .unwrap()
        .contains("missing"));
}

#[test]
fn milestone_prepare_evidence_inputs_writes_secret_free_manifest_templates_with_approval() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("foundry.sqlite");
    let project = temp.path().join("prepare-project");

    let dry_run_output = foundry()
        .arg("--store")
        .arg(store.to_str().unwrap())
        .args([
            "milestone",
            "prepare-evidence-inputs",
            "--version",
            "0.5",
            "--capability",
            "replacement_grade_cli",
            "--project-root",
        ])
        .arg(project.to_str().unwrap())
        .args(["--connected-brain", "project-provider", "--output", "json"])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let dry_run_json: Value = serde_json::from_slice(&dry_run_output).unwrap();
    assert_eq!(
        dry_run_json["schema_version"],
        "foundry.milestone.prepare_evidence_inputs.v1"
    );
    assert_eq!(dry_run_json["status"], "manifest_templates_planned");
    assert_eq!(dry_run_json["mutates_files"], false);
    assert_eq!(dry_run_json["apply"], false);
    assert_eq!(dry_run_json["template_count"], 1);
    assert_eq!(dry_run_json["written_count"], 0);
    assert_eq!(dry_run_json["skipped_count"], 1);
    assert_eq!(
        dry_run_json["prepared_files"][0]["template_id"],
        "connected_brain_runtime_manifest"
    );
    assert_eq!(
        dry_run_json["prepared_files"][0]["target_path"],
        project
            .join(".foundry/connected-brain-runtimes.json")
            .display()
            .to_string()
    );
    assert_eq!(dry_run_json["prepared_files"][0]["write_status"], "planned");
    assert_eq!(dry_run_json["prepared_files"][0]["secret_free"], true);
    assert!(!project
        .join(".foundry/connected-brain-runtimes.json")
        .exists());

    let apply_output = foundry()
        .arg("--store")
        .arg(store.to_str().unwrap())
        .args([
            "milestone",
            "prepare-evidence-inputs",
            "--version",
            "0.5",
            "--capability",
            "replacement_grade_cli",
            "--project-root",
        ])
        .arg(project.to_str().unwrap())
        .args([
            "--connected-brain",
            "project-provider",
            "--apply",
            "--approved-by",
            "arthur",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let apply_json: Value = serde_json::from_slice(&apply_output).unwrap();
    assert_eq!(apply_json["status"], "manifest_templates_written");
    assert_eq!(apply_json["mutates_files"], true);
    assert_eq!(apply_json["apply"], true);
    assert_eq!(apply_json["approved_by"], "arthur");
    assert_eq!(apply_json["written_count"], 1);
    assert_eq!(apply_json["prepared_files"][0]["write_status"], "written");
    assert_eq!(apply_json["prepared_files"][0]["existed_before"], false);
    assert_eq!(apply_json["prepared_files"][0]["created_parent_dir"], true);
    assert!(apply_json["next_commands"]
        .as_array()
        .unwrap()
        .iter()
        .any(|command| command
            .as_str()
            .unwrap()
            .contains("foundry milestone evidence-plan --version 0.6")));

    let manifest_path = project.join(".foundry/connected-brain-runtimes.json");
    let manifest: Value = serde_json::from_slice(&fs::read(&manifest_path).unwrap()).unwrap();
    assert_eq!(manifest["providers"][0]["id"], "project-provider");
    assert_eq!(manifest["providers"][0]["network_access"], false);
    assert_eq!(manifest["providers"][0]["allow_model_execution"], true);

    let repair_plan_output = foundry()
        .arg("--store")
        .arg(store.to_str().unwrap())
        .args([
            "milestone",
            "prepare-evidence-inputs",
            "--version",
            "0.5",
            "--capability",
            "replacement_grade_cli",
            "--project-root",
        ])
        .arg(project.to_str().unwrap())
        .args(["--connected-brain", "project-provider", "--output", "json"])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let repair_plan_json: Value = serde_json::from_slice(&repair_plan_output).unwrap();
    assert_eq!(repair_plan_json["status"], "manifest_templates_planned");
    assert_eq!(repair_plan_json["template_count"], 1);
    assert_eq!(
        repair_plan_json["prepared_files"][0]["existed_before"],
        true
    );
    assert_eq!(
        repair_plan_json["prepared_files"][0]["write_status"],
        "planned"
    );

    foundry()
        .arg("--store")
        .arg(store.to_str().unwrap())
        .args([
            "milestone",
            "prepare-evidence-inputs",
            "--version",
            "0.5",
            "--capability",
            "replacement_grade_cli",
            "--project-root",
        ])
        .arg(project.to_str().unwrap())
        .args([
            "--connected-brain",
            "project-provider",
            "--apply",
            "--approved-by",
            "arthur",
            "--output",
            "json",
        ])
        .assert()
        .failure()
        .stderr(predicates::str::contains("refusing to overwrite"));

    let overwrite_project = temp.path().join("overwrite-project");
    fs::create_dir_all(overwrite_project.join(".foundry")).unwrap();
    fs::write(
        overwrite_project.join(".foundry/connected-brain-runtimes.json"),
        "{}",
    )
    .unwrap();
    foundry()
        .arg("--store")
        .arg(store.to_str().unwrap())
        .args([
            "milestone",
            "prepare-evidence-inputs",
            "--version",
            "0.5",
            "--capability",
            "replacement_grade_cli",
            "--project-root",
        ])
        .arg(overwrite_project.to_str().unwrap())
        .args([
            "--connected-brain",
            "project-provider",
            "--apply",
            "--approved-by",
            "arthur",
            "--output",
            "json",
        ])
        .assert()
        .failure()
        .stderr(predicates::str::contains("refusing to overwrite"));

    let multimodal_output = foundry()
        .arg("--store")
        .arg(store.to_str().unwrap())
        .args([
            "milestone",
            "prepare-evidence-inputs",
            "--version",
            "0.5",
            "--capability",
            "experimental_multimodal_runtime",
            "--project-root",
        ])
        .arg(project.to_str().unwrap())
        .args([
            "--connected-runtime",
            "production-vision-runtime",
            "--apply",
            "--approved-by",
            "arthur",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let multimodal_json: Value = serde_json::from_slice(&multimodal_output).unwrap();
    assert_eq!(multimodal_json["template_count"], 2);
    assert_eq!(multimodal_json["written_count"], 2);
    assert!(project.join(".foundry/multimodal.json").exists());
    assert!(project.join(".foundry/multimodal-runtimes.json").exists());

    let multimodal_repair_output = foundry()
        .arg("--store")
        .arg(store.to_str().unwrap())
        .args([
            "milestone",
            "prepare-evidence-inputs",
            "--version",
            "0.5",
            "--capability",
            "experimental_multimodal_runtime",
            "--project-root",
        ])
        .arg(project.to_str().unwrap())
        .args([
            "--connected-runtime",
            "production-vision-runtime",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let multimodal_repair_json: Value = serde_json::from_slice(&multimodal_repair_output).unwrap();
    assert_eq!(
        multimodal_repair_json["status"],
        "manifest_templates_planned"
    );
    assert_eq!(multimodal_repair_json["template_count"], 2);
    assert!(multimodal_repair_json["prepared_files"]
        .as_array()
        .unwrap()
        .iter()
        .any(|file| file["template_id"] == "multimodal_feature_flag"
            && file["existed_before"] == true));
    assert!(multimodal_repair_json["prepared_files"]
        .as_array()
        .unwrap()
        .iter()
        .any(|file| file["template_id"] == "multimodal_runtime_manifest"
            && file["existed_before"] == true));
}

#[test]
fn milestone_prepare_evidence_inputs_can_materialize_approved_connected_brain_wrapper_manifest() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("foundry.sqlite");
    let project = temp.path().join("approved-provider-project");
    let wrapper = project.join(".foundry/bin/codex");
    fs::create_dir_all(wrapper.parent().unwrap()).unwrap();
    fs::write(&wrapper, "#!/usr/bin/env sh\necho '{\"status\":\"ok\"}'\n").unwrap();
    #[cfg(unix)]
    {
        let mut permissions = fs::metadata(&wrapper).unwrap().permissions();
        permissions.set_mode(0o755);
        fs::set_permissions(&wrapper, permissions).unwrap();
    }

    let apply_output = foundry()
        .arg("--store")
        .arg(store.to_str().unwrap())
        .args([
            "milestone",
            "prepare-evidence-inputs",
            "--version",
            "0.5",
            "--capability",
            "replacement_grade_cli",
            "--project-root",
        ])
        .arg(project.to_str().unwrap())
        .args(["--connected-brain", "codex", "--provider-command"])
        .arg(wrapper.to_str().unwrap())
        .args([
            "--model-id",
            "codex-cli-approved-test",
            "--approval-ref",
            "change-123",
            "--apply",
            "--approved-by",
            "arthur",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let apply_json: Value = serde_json::from_slice(&apply_output).unwrap();
    assert_eq!(apply_json["status"], "manifest_templates_written");
    assert_eq!(
        apply_json["promotion_impact"],
        "prepares_inputs_only_not_evidence_not_auto_promoted"
    );
    assert_eq!(
        apply_json["evidence_plan"]["ready_to_collect_evidence"],
        false
    );
    assert_eq!(apply_json["approved_by"], "arthur");

    let manifest_path = project.join(".foundry/connected-brain-runtimes.json");
    let manifest: Value = serde_json::from_slice(&fs::read(&manifest_path).unwrap()).unwrap();
    let provider = &manifest["providers"][0];
    assert_eq!(provider["id"], "codex");
    assert_eq!(provider["brain_id"], "codex");
    assert_eq!(provider["provider_class"], "external_cli");
    assert_eq!(provider["command"][0], wrapper.display().to_string());
    assert_eq!(provider["approved_by"], "arthur");
    assert_eq!(provider["approval_ref"], "change-123");
    assert_eq!(provider["model_id"], "codex-cli-approved-test");
    assert_eq!(provider["allow_model_execution"], true);
    assert_eq!(provider["network_access"], false);
    assert_eq!(provider["device_access"], false);
    assert_eq!(provider["external_resources_mutated"], false);
    assert!(provider["capabilities"]
        .as_array()
        .unwrap()
        .contains(&serde_json::json!("replacement_grade_cli")));

    let plan_output = foundry()
        .arg("--store")
        .arg(store.to_str().unwrap())
        .args([
            "milestone",
            "evidence-plan",
            "--version",
            "0.5",
            "--capability",
            "replacement_grade_cli",
            "--project-root",
        ])
        .arg(project.to_str().unwrap())
        .args(["--connected-brain", "codex", "--output", "json"])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let plan_json: Value = serde_json::from_slice(&plan_output).unwrap();
    assert_eq!(plan_json["status"], "evidence_inputs_ready");
    assert_eq!(plan_json["ready_to_collect_evidence"], true);
    assert!(plan_json["manifest_templates"]
        .as_array()
        .unwrap()
        .is_empty());
    assert!(plan_json["config_checks"]
        .as_array()
        .unwrap()
        .iter()
        .any(|check| check["id"] == "connected_brain_provider"
            && check["status"] == "ready"
            && check["selected_id"] == "codex"));
    assert!(plan_json["config_checks"]
        .as_array()
        .unwrap()
        .iter()
        .any(|check| check["id"] == "connected_brain_provider_command"
            && check["status"] == "ready"
            && check["path"] == wrapper.display().to_string()));
    assert!(plan_json["evidence_collection_commands"]
        .as_array()
        .unwrap()
        .iter()
        .any(|command| command
            .as_str()
            .unwrap()
            .contains("collect-evidence --version 0.6")));

    let manifest_output = foundry()
        .args(["mcp", "tools", "--output", "json"])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let manifest_json: Value = serde_json::from_slice(&manifest_output).unwrap();
    let tool = find_mcp_tool(&manifest_json, "foundry.milestone.prepare_evidence_inputs");
    assert_eq!(
        tool["input_schema"]["properties"]["provider_command"]["type"],
        "string"
    );
    assert_eq!(
        tool["input_schema"]["properties"]["model_id"]["type"],
        "string"
    );
    assert_eq!(
        tool["input_schema"]["properties"]["approval_ref"]["type"],
        "string"
    );
}

