#[test]
fn milestone_collect_evidence_runs_ready_sources_and_attaches_receipts() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("foundry.sqlite");
    let project = temp.path().join("collect-project");
    let foundry_dir = project.join(".foundry");
    fs::create_dir_all(&foundry_dir).unwrap();

    let provider_script = temp.path().join("real-provider.sh");
    fs::write(
        &provider_script,
        r#"#!/bin/sh
set -eu
mkdir -p brain-output
cat > brain-output/plan.json <<EOF
{"schema_version":"foundry.connected_external_brain.provider_plan.v1","workflow_id":"$FOUNDRY_WORKFLOW_ID","task_id":"$FOUNDRY_TASK_ID","run_id":"$FOUNDRY_RUN_ID","brain_id":"real-provider","model_execution_performed":true}
EOF
cat > brain-output/provider-output.json <<EOF
{"schema_version":"foundry.connected_external_brain.provider_output.v1","provider_id":"real-provider","quality_score":0.98,"latency_ms":10,"model_execution_performed":true,"real_provider_execution_performed":true}
EOF
cat > brain-output/research.md <<EOF
# Real provider evidence

- Workflow: $FOUNDRY_WORKFLOW_ID
- Provider: real-provider
EOF
cat > brain-output/code.rs <<'RS'
pub fn real_provider_marker() -> &'static str {
    "real-provider"
}
RS
printf 'real_provider_ok\n'
"#,
    )
    .unwrap();
    let mut perms = fs::metadata(&provider_script).unwrap().permissions();
    perms.set_mode(0o755);
    fs::set_permissions(&provider_script, perms).unwrap();

    fs::write(
        foundry_dir.join("connected-brain-runtimes.json"),
        serde_json::to_string_pretty(&serde_json::json!({
            "providers": [{
                "id": "real-provider",
                "brain_id": "real-provider",
                "model_id": "real-provider-model-v1",
                "provider_class": "external_cli",
                "capabilities": ["replacement_grade_cli"],
                "command": [provider_script.display().to_string()],
                "approved_by": "arthur",
                "approval_ref": "provider-approval-collect-001",
                "allow_model_execution": true,
                "network_access": false,
                "device_access": false,
                "external_resources_mutated": false
            }]
        }))
        .unwrap(),
    )
    .unwrap();
    fs::write(
        foundry_dir.join("multimodal.json"),
        r#"{"experimental_enabled":true,"approved_by":"arthur","reason":"collect production runtime evidence","scope":"project"}"#,
    )
    .unwrap();
    fs::write(
        foundry_dir.join("multimodal-runtimes.json"),
        serde_json::to_string_pretty(&serde_json::json!({
            "runtimes": [{
                "id": "production-vision-runtime",
                "model_id": "vision-prod-model-v3",
                "capabilities": ["image_understanding"],
                "probe_command": [
                    "/bin/sh",
                    "-c",
                    "printf '{\"labels\":[\"document\",\"production-runtime\"],\"quality_score\":0.97,\"latency_ms\":12}'"
                ],
                "network_access": false,
                "device_access": false,
                "production": {
                    "approved_by": "arthur",
                    "approval_ref": "runtime-approval-collect-001",
                    "runtime_version": "vision-runtime 3.2.1",
                    "model_manifest_sha256": "cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc",
                    "model_license": "internal-production-approved",
                    "evidence_artifacts": ["benchmarks/vision-prod-collect.json"],
                    "min_quality_score": 0.95,
                    "max_latency_ms": 20
                }
            }]
        }))
        .unwrap(),
    )
    .unwrap();

    let provider_output = foundry()
        .arg("--store")
        .arg(store.to_str().unwrap())
        .args([
            "milestone",
            "collect-evidence",
            "--version",
            "0.5",
            "--capability",
            "replacement_grade_cli",
            "--project-root",
        ])
        .arg(project.to_str().unwrap())
        .args([
            "--connected-brain",
            "real-provider",
            "--approved-by",
            "arthur",
            "--origin",
            "codex",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let provider_json: Value = serde_json::from_slice(&provider_output).unwrap();
    assert_eq!(
        provider_json["schema_version"],
        "foundry.milestone.collect_evidence.v1"
    );
    assert_eq!(provider_json["capability_id"], "replacement_grade_cli");
    assert_eq!(provider_json["kind"], "external_brain_provider_execution");
    assert_eq!(provider_json["status"], "collected_and_attached");
    assert_eq!(provider_json["collection_promotion_ready"], true);
    assert_eq!(
        provider_json["attached_evidence"]["schema_version"],
        "foundry.milestone.attached_evidence.v1"
    );
    assert_eq!(
        provider_json["attached_evidence"]["kind"],
        "external_brain_provider_execution"
    );
    let provider_artifact: Value = serde_json::from_slice(
        &fs::read(provider_json["collection_artifact_path"].as_str().unwrap()).unwrap(),
    )
    .unwrap();
    assert_eq!(provider_artifact["collection_promotion_ready"], true);
    assert!(provider_artifact["promotion_gates"]
        .as_array()
        .unwrap()
        .iter()
        .any(|gate| gate["id"] == "real_provider_execution_performed" && gate["passed"] == true));
    assert!(provider_artifact["promotion_gates"]
        .as_array()
        .unwrap()
        .iter()
        .any(|gate| gate["id"] == "harness_exec_event_recorded" && gate["passed"] == true));
    assert!(
        provider_json["attached_evidence"]["global_event_id"]
            .as_i64()
            .unwrap()
            > 0
    );

    let multimodal_output = foundry()
        .arg("--store")
        .arg(store.to_str().unwrap())
        .args([
            "milestone",
            "collect-evidence",
            "--version",
            "0.5",
            "--capability",
            "experimental_multimodal_runtime",
            "--project-root",
        ])
        .arg(project.to_str().unwrap())
        .args([
            "--connected-runtime",
            "production-vision-runtime",
            "--approved-by",
            "arthur",
            "--origin",
            "codex",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let multimodal_json: Value = serde_json::from_slice(&multimodal_output).unwrap();
    assert_eq!(
        multimodal_json["schema_version"],
        "foundry.milestone.collect_evidence.v1"
    );
    assert_eq!(
        multimodal_json["capability_id"],
        "experimental_multimodal_runtime"
    );
    assert_eq!(multimodal_json["kind"], "production_runtime_benchmark");
    assert_eq!(multimodal_json["status"], "collected_and_attached");
    assert_eq!(multimodal_json["collection_promotion_ready"], true);
    assert_eq!(
        multimodal_json["attached_evidence"]["kind"],
        "production_runtime_benchmark"
    );
    let multimodal_artifact: Value = serde_json::from_slice(
        &fs::read(
            multimodal_json["collection_artifact_path"]
                .as_str()
                .unwrap(),
        )
        .unwrap(),
    )
    .unwrap();
    assert_eq!(multimodal_artifact["collection_promotion_ready"], true);
    assert!(multimodal_artifact["promotion_gates"]
        .as_array()
        .unwrap()
        .iter()
        .any(|gate| gate["id"] == "runtime_benchmark_promotion_ready" && gate["passed"] == true));
    assert!(multimodal_artifact["promotion_gates"]
        .as_array()
        .unwrap()
        .iter()
        .any(|gate| gate["id"] == "network_access_blocked" && gate["passed"] == true));

    let manifest_output = foundry()
        .arg("--store")
        .arg(store.to_str().unwrap())
        .args([
            "milestone",
            "manifest",
            "--version",
            "0.5",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let manifest_json: Value = serde_json::from_slice(&manifest_output).unwrap();
    let attached = manifest_json["attached_evidence"].as_array().unwrap();
    assert!(attached.iter().any(|evidence| {
        evidence["capability_id"] == "replacement_grade_cli"
            && evidence["kind"] == "external_brain_provider_execution"
    }));
    assert!(attached.iter().any(|evidence| {
        evidence["capability_id"] == "experimental_multimodal_runtime"
            && evidence["kind"] == "production_runtime_benchmark"
    }));
    assert_eq!(manifest_json["promotion_decision"]["decision"], "promote");
}

#[test]
fn milestone_collect_evidence_selects_replacement_cli_demo_evidence_kinds() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("foundry.sqlite");
    persist_ready_executor_state(&store, "codex");
    let project = temp.path().join("collect-demo-kinds-project");
    fs::create_dir_all(&project).unwrap();

    for kind in [
        "broader_project_coding_research_workflow",
        "terminal_file_editing_ux",
    ] {
        let output = foundry()
            .arg("--store")
            .arg(store.to_str().unwrap())
            .args([
                "milestone",
                "collect-evidence",
                "--version",
                "0.5",
                "--capability",
                "replacement_grade_cli",
                "--kind",
                kind,
                "--project-root",
            ])
            .arg(project.to_str().unwrap())
            .args([
                "--approved-by",
                "arthur",
                "--origin",
                "codex",
                "--output",
                "json",
            ])
            .assert()
            .success()
            .get_output()
            .stdout
            .clone();
        let json: Value = serde_json::from_slice(&output).unwrap();
        assert_eq!(
            json["schema_version"],
            "foundry.milestone.collect_evidence.v1"
        );
        assert_eq!(json["capability_id"], "replacement_grade_cli");
        assert_eq!(json["kind"], kind);
        assert_eq!(json["status"], "collected_and_attached");
        assert_eq!(json["collection_promotion_ready"], true);
        assert_eq!(json["attached_evidence"]["kind"], kind);
        assert!(json["promotion_gates"]
            .as_array()
            .unwrap()
            .iter()
            .all(|gate| gate["passed"] == true));
        assert_eq!(
            json["promotion_impact"],
            "collected_and_attached_not_auto_promoted"
        );

        let artifact: Value = serde_json::from_slice(
            &fs::read(json["collection_artifact_path"].as_str().unwrap()).unwrap(),
        )
        .unwrap();
        assert_eq!(artifact["collection_promotion_ready"], true);
        let gates = artifact["promotion_gates"].as_array().unwrap();
        assert!(
            gates.iter().all(|gate| gate["passed"] == true
                && gate["id"].as_str().unwrap_or_default().contains('_')
                && !gate["summary"].as_str().unwrap_or_default().is_empty()),
            "every collected evidence artifact should expose explicit passed promotion gates"
        );
        match kind {
            "broader_project_coding_research_workflow" => {
                assert!(gates.iter().any(|gate| gate["id"] == "handoff_ready"));
                assert!(gates.iter().any(|gate| gate["id"] == "exec_event_recorded"));
                assert!(gates
                    .iter()
                    .any(|gate| gate["id"] == "validated_multi_file_artifacts"));
            }
            "terminal_file_editing_ux" => {
                assert!(gates.iter().any(|gate| gate["id"] == "review_before_apply"));
                assert!(gates
                    .iter()
                    .any(|gate| gate["id"] == "restore_approval_recorded"));
                assert!(gates
                    .iter()
                    .any(|gate| gate["id"] == "restored_to_clean_state"));
            }
            _ => unreachable!("unexpected evidence kind in test"),
        }
    }

    let manifest_output = foundry()
        .arg("--store")
        .arg(store.to_str().unwrap())
        .args([
            "milestone",
            "manifest",
            "--version",
            "0.5",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let manifest_json: Value = serde_json::from_slice(&manifest_output).unwrap();
    let attached = manifest_json["attached_evidence"].as_array().unwrap();
    assert!(attached.iter().any(|evidence| {
        evidence["capability_id"] == "replacement_grade_cli"
            && evidence["kind"] == "broader_project_coding_research_workflow"
    }));
    assert!(attached.iter().any(|evidence| {
        evidence["capability_id"] == "replacement_grade_cli"
            && evidence["kind"] == "terminal_file_editing_ux"
    }));
    assert_eq!(manifest_json["promotion_decision"]["decision"], "promote");
}

#[test]
fn milestone_collect_ready_evidence_collects_ready_receipts_and_reports_skips() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("foundry.sqlite");
    persist_ready_executor_state(&store, "codex");
    let project = temp.path().join("collect-ready-project");
    fs::create_dir_all(&project).unwrap();

    let output = foundry()
        .arg("--store")
        .arg(store.to_str().unwrap())
        .args([
            "milestone",
            "collect-ready-evidence",
            "--version",
            "0.5",
            "--project-root",
        ])
        .arg(project.to_str().unwrap())
        .args([
            "--approved-by",
            "arthur",
            "--origin",
            "codex",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();

    let json: Value = serde_json::from_slice(&output).unwrap();
    assert_eq!(
        json["schema_version"],
        "foundry.milestone.collect_ready_evidence.v1"
    );
    assert_eq!(json["milestone"], "0.6");
    assert_eq!(json["status"], "partial_collection");
    assert_eq!(json["project_root"], project.display().to_string());
    assert_eq!(json["approved_by"], "arthur");
    assert_eq!(json["origin"], "codex");
    assert_eq!(json["required_count"], 4);
    assert_eq!(json["collected_count"], 2);
    assert_eq!(json["skipped_count"], 2);
    assert_eq!(json["failed_count"], 0);
    assert_eq!(json["promotion_ready_after_collection"], true);
    assert_eq!(
        json["promotion_decision_after_collection"]["decision"],
        "promote"
    );

    let collected = json["collected_evidence"].as_array().unwrap();
    assert!(collected.iter().any(|item| {
        item["capability_id"] == "replacement_grade_cli"
            && item["kind"] == "broader_project_coding_research_workflow"
            && item["status"] == "collected_and_attached"
    }));
    assert!(collected.iter().any(|item| {
        item["capability_id"] == "replacement_grade_cli"
            && item["kind"] == "terminal_file_editing_ux"
            && item["status"] == "collected_and_attached"
    }));

    let skipped = json["skipped_evidence"].as_array().unwrap();
    assert!(skipped.iter().any(|item| {
        item["capability_id"] == "replacement_grade_cli"
            && item["kind"] == "external_brain_provider_execution"
            && item["status"] == "not_ready_to_collect"
            && item["evidence_plan"]["ready_to_collect_evidence"] == false
    }));
    assert!(skipped.iter().any(|item| {
        item["capability_id"] == "experimental_multimodal_runtime"
            && item["kind"] == "production_runtime_benchmark"
            && item["status"] == "not_ready_to_collect"
            && item["evidence_plan"]["ready_to_collect_evidence"] == false
    }));
    assert!(json["next_commands"]
        .as_array()
        .unwrap()
        .iter()
        .any(|command| command
            .as_str()
            .unwrap()
            .contains("foundry milestone evidence-plan --version 0.6")));

    let manifest_output = foundry()
        .arg("--store")
        .arg(store.to_str().unwrap())
        .args([
            "milestone",
            "manifest",
            "--version",
            "0.5",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let manifest_json: Value = serde_json::from_slice(&manifest_output).unwrap();
    let attached = manifest_json["attached_evidence"].as_array().unwrap();
    assert!(attached.iter().any(|evidence| {
        evidence["capability_id"] == "replacement_grade_cli"
            && evidence["kind"] == "broader_project_coding_research_workflow"
    }));
    assert!(attached.iter().any(|evidence| {
        evidence["capability_id"] == "replacement_grade_cli"
            && evidence["kind"] == "terminal_file_editing_ux"
    }));
    assert_eq!(manifest_json["promotion_decision"]["decision"], "promote");
}

#[test]
fn historical_05_boundary_document_remains_available_as_immutable_evidence() {
    // foundry-brand-allow: historical-release
    let docs = fs::read_to_string("docs/forge-0.5-milestone.md").unwrap();

    assert!(
        docs.contains("| Export/demo baseline | validated |"),
        "the visible 0.5 milestone boundary must match the runtime manifest after export-demo validation"
    );
    assert!(
        docs.contains("milestone export-demo"),
        "the historical boundary should preserve export-demo validation evidence"
    );
    assert!(
        docs.contains("promotion decision"),
        "the milestone boundary should explain that promotion is a gated runtime decision"
    );
    assert!(
        docs.contains("| Replacement-grade") && docs.contains("CLI | groundwork |"),
        "the historical boundary must preserve replacement-grade CLI scope"
    );
    assert!(
        docs.contains("| Experimental multimodal runtime | groundwork |"),
        "the visible 0.5 milestone boundary must include the new disabled-by-default multimodal scope"
    );
    assert!(
        docs.contains("multimodal benchmark-template"),
        "the historical boundary should preserve benchmark-template evidence"
    );
    assert!(
        // foundry-brand-allow: historical-release
        docs.contains("forge multimodal demo-plan"),
        "the visible 0.5 milestone boundary should point to guarded demo-plan evidence"
    );
    assert!(
        // foundry-brand-allow: historical-release
        docs.contains("forge multimodal benchmark-result"),
        "the visible 0.5 milestone boundary should point to approved fixture-only benchmark result evidence"
    );
    assert!(
        // foundry-brand-allow: historical-release
        docs.contains("forge multimodal runtime-benchmark"),
        "the visible 0.5 milestone boundary should point to guarded runtime benchmark evidence"
    );
    assert!(
        // foundry-brand-allow: historical-release
        docs.contains("forge multimodal demo-receipt"),
        "the visible 0.5 milestone boundary should point to guarded demo receipt evidence"
    );
    assert!(
        // foundry-brand-allow: historical-release
        docs.contains("forge.multimodal.benchmark_result"),
        "the visible 0.5 milestone boundary should expose the MCP benchmark result surface"
    );
    assert!(
        // foundry-brand-allow: historical-release
        docs.contains("forge.multimodal.runtime_benchmark"),
        "the visible 0.5 milestone boundary should expose the MCP runtime benchmark surface"
    );
    assert!(
        // foundry-brand-allow: historical-release
        docs.contains("forge.multimodal.demo_receipt"),
        "the visible 0.5 milestone boundary should expose the MCP demo receipt surface"
    );
    assert!(
        // foundry-brand-allow: historical-release
        docs.contains(".forge/multimodal.json"),
        "the visible 0.5 milestone boundary should point to explicit multimodal feature-flag config"
    );
    assert!(
        // foundry-brand-allow: historical-release
        docs.contains("forge.addon.multimodal"),
        "the visible 0.5 milestone boundary should state that multimodal is Addon-owned"
    );
    assert!(
        // foundry-brand-allow: historical-release
        docs.contains("forge.addons.run_dispatch"),
        "the visible 0.5 milestone boundary should include Addon runtime dispatch evidence"
    );
    assert!(
        // foundry-brand-allow: historical-release
        docs.contains("forge milestone cli-demo"),
        "the visible 0.5 milestone boundary should point to replacement-grade CLI demo evidence"
    );
    assert!(
        // foundry-brand-allow: historical-release
        docs.contains("forge.milestone.cli_demo"),
        "the visible 0.5 milestone boundary should expose the MCP CLI demo surface"
    );
    assert!(
        // foundry-brand-allow: historical-release
        docs.contains("forge interactive command-palette"),
        "the visible 0.5 milestone boundary should point to the replacement-grade command palette"
    );
    assert!(
        // foundry-brand-allow: historical-release
        docs.contains("forge.interactive.command_palette"),
        "the visible 0.5 milestone boundary should expose the MCP command palette surface"
    );
    assert!(
        // foundry-brand-allow: historical-release
        docs.contains("forge interactive autocomplete"),
        "the visible 0.5 milestone boundary should point to the replacement-grade autocomplete surface"
    );
    assert!(
        // foundry-brand-allow: historical-release
        docs.contains("forge.interactive.autocomplete"),
        "the visible 0.5 milestone boundary should expose the MCP autocomplete surface"
    );
    assert!(
        // foundry-brand-allow: historical-release
        docs.contains("forge milestone collect-ready-evidence"),
        "the visible 0.5 milestone boundary should expose the ready evidence collector"
    );
    assert!(
        // foundry-brand-allow: historical-release
        docs.contains("forge.milestone.collect_ready_evidence"),
        "the visible 0.5 milestone boundary should expose the MCP ready evidence collector"
    );
    assert!(
        docs.contains("Full terminal TUI loop and richer inline mode"),
        "the visible 0.5 milestone boundary should no longer list autocomplete as missing after autocomplete evidence exists"
    );
}

#[test]
fn packaged_skill_mentions_export_demo_agent_surface() {
    assert!(
        foundry_core::skill::AGENT_REFERENCE_MD.contains("foundry milestone export-demo"),
        "the packaged Foundry skill should teach agents how to generate export/demo evidence"
    );
    assert!(
        foundry_core::skill::AGENT_REFERENCE_MD.contains("foundry.milestone.export_demo"),
        "the packaged Foundry skill should expose the MCP export-demo tool to agent callers"
    );
    assert!(
        foundry_core::skill::AGENT_REFERENCE_MD.contains("foundry milestone prepare-evidence-inputs"),
        "the packaged Foundry skill should teach agents how to materialize secret-free milestone evidence input manifests"
    );
    assert!(
        foundry_core::skill::AGENT_REFERENCE_MD.contains("--provider-command <absolute-provider-adapter-path>")
            && foundry_core::skill::AGENT_REFERENCE_MD.contains("--model-id <approved-model-id>")
            && foundry_core::skill::AGENT_REFERENCE_MD.contains("--approval-ref <approval-ref>"),
        "the packaged Foundry skill should teach agents how to prepare an approved connected-brain provider adapter manifest without collecting evidence"
    );
    assert!(
        foundry_core::skill::AGENT_REFERENCE_MD.contains("foundry.milestone.prepare_evidence_inputs"),
        "the packaged Foundry skill should expose the MCP prepare-evidence-inputs tool to agent callers"
    );
    assert!(
        foundry_core::skill::AGENT_REFERENCE_MD.contains("foundry milestone collect-ready-evidence"),
        "the packaged Foundry skill should teach agents how to collect all ready milestone evidence without overclaiming promotion"
    );
    assert!(
        foundry_core::skill::AGENT_REFERENCE_MD.contains("foundry.milestone.collect_ready_evidence"),
        "the packaged Foundry skill should expose the MCP collect-ready-evidence tool to agent callers"
    );
}

#[test]
fn packaged_skill_mentions_experimental_multimodal_agent_surface() {
    assert!(
        foundry_core::skill::AGENT_REFERENCE_MD.contains("foundry.addon.multimodal"),
        "the packaged Foundry skill should identify multimodal as an Addon-owned capability"
    );
    assert!(
        foundry_core::skill::AGENT_REFERENCE_MD.contains("multimodal_runtime"),
        "the packaged Foundry skill should teach agents to resolve multimodal through the Addon capability"
    );
    assert!(
        foundry_core::skill::AGENT_REFERENCE_MD.contains("foundry.addons.run_dispatch"),
        "the packaged Foundry skill should expose the Addon runtime dispatch path for multimodal execution"
    );
    assert!(
        foundry_core::skill::AGENT_REFERENCE_MD.contains("foundry multimodal status"),
        "the packaged Foundry skill should teach agents how to inspect experimental multimodal status"
    );
    assert!(
        foundry_core::skill::AGENT_REFERENCE_MD.contains("foundry.multimodal.status"),
        "the packaged Foundry skill should expose the MCP multimodal status tool to agent callers"
    );
    assert!(
        foundry_core::skill::AGENT_REFERENCE_MD.contains("foundry multimodal guard"),
        "the packaged Foundry skill should teach agents to route camera/screen/input access through runtime guards"
    );
}

#[test]
fn packaged_skill_mentions_multimodal_benchmark_and_demo_plan_surfaces() {
    assert!(
        foundry_core::skill::AGENT_REFERENCE_MD.contains("foundry multimodal benchmark-template"),
        "the packaged Foundry skill should teach agents how to generate multimodal benchmark templates"
    );
    assert!(
        foundry_core::skill::AGENT_REFERENCE_MD.contains("foundry.multimodal.benchmark_template"),
        "the packaged Foundry skill should expose the MCP benchmark-template tool to agent callers"
    );
    assert!(
        foundry_core::skill::AGENT_REFERENCE_MD.contains("foundry multimodal readiness"),
        "the packaged Foundry skill should teach agents how to inspect multimodal runtime/model readiness without executing models"
    );
    assert!(
        foundry_core::skill::AGENT_REFERENCE_MD.contains("foundry.multimodal.readiness"),
        "the packaged Foundry skill should expose the MCP readiness tool to agent callers"
    );
    assert!(
        foundry_core::skill::AGENT_REFERENCE_MD.contains("foundry multimodal benchmark-result"),
        "the packaged Foundry skill should teach agents how to record approved fixture-only benchmark results"
    );
    assert!(
        foundry_core::skill::AGENT_REFERENCE_MD.contains("foundry.multimodal.benchmark_result"),
        "the packaged Foundry skill should expose the MCP benchmark-result tool to agent callers"
    );
    assert!(
        foundry_core::skill::AGENT_REFERENCE_MD.contains("foundry multimodal runtime-benchmark"),
        "the packaged Foundry skill should teach agents how to run guarded runtime benchmarks"
    );
    assert!(
        foundry_core::skill::AGENT_REFERENCE_MD.contains("foundry.multimodal.runtime_benchmark"),
        "the packaged Foundry skill should expose the MCP runtime-benchmark tool to agent callers"
    );
    assert!(
        foundry_core::skill::AGENT_REFERENCE_MD.contains(".foundry/multimodal.json"),
        "the packaged Foundry skill should teach agents where explicit multimodal feature-flag config lives"
    );
    assert!(
        foundry_core::skill::AGENT_REFERENCE_MD.contains(".foundry/multimodal-runtimes.json"),
        "the packaged Foundry skill should teach agents where connected multimodal runtime manifests live"
    );
    assert!(
        foundry_core::skill::AGENT_REFERENCE_MD.contains("--connected-runtime"),
        "the packaged Foundry skill should teach agents how to select an approved connected runtime benchmark"
    );
    assert!(
        foundry_core::skill::AGENT_REFERENCE_MD.contains("\"project_root\""),
        "the packaged Foundry skill should expose project-root based multimodal MCP inspection"
    );
    assert!(
        foundry_core::skill::AGENT_REFERENCE_MD.contains("foundry multimodal demo-plan"),
        "the packaged Foundry skill should teach agents how to generate guarded multimodal demo plans"
    );
    assert!(
        foundry_core::skill::AGENT_REFERENCE_MD.contains("foundry.multimodal.demo_plan"),
        "the packaged Foundry skill should expose the MCP demo-plan tool to agent callers"
    );
    assert!(
        foundry_core::skill::AGENT_REFERENCE_MD.contains("foundry multimodal demo-receipt"),
        "the packaged Foundry skill should teach agents how to record guarded multimodal demo receipts"
    );
    assert!(
        foundry_core::skill::AGENT_REFERENCE_MD.contains("foundry.multimodal.demo_receipt"),
        "the packaged Foundry skill should expose the MCP demo-receipt tool to agent callers"
    );
}

