#[test]
fn mcp_exposes_milestone_manifest_for_agent_release_gates() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("foundry.sqlite");

    let tools = foundry()
        .args(["mcp", "tools", "--output", "json"])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let manifest: Value = serde_json::from_slice(&tools).unwrap();
    assert!(manifest["tools"].as_array().unwrap().iter().any(|tool| {
        tool["name"] == "foundry.milestone.manifest"
            && tool["output_schema"] == "foundry.milestone.manifest.v1"
            && tool["async_safe"] == true
            && tool["mutates_workflow"] == false
    }));

    let call = foundry()
        .arg("--store")
        .arg(store.to_str().unwrap())
        .args(["mcp", "call", "foundry.milestone.manifest"])
        .arg("--input")
        .arg(r#"{"version":"0.5"}"#)
        .args(["--output", "json"])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();

    let json: Value = serde_json::from_slice(&call).unwrap();
    assert_eq!(json["status"], "ok");
    assert_eq!(
        json["result"]["schema_version"],
        "foundry.milestone.manifest.v1"
    );
    assert_eq!(json["result"]["milestone"], "0.6");
    assert!(json["result"]["completed_capabilities"]
        .as_array()
        .unwrap()
        .iter()
        .any(|capability| capability["id"] == "research_artifact_baseline"));
    assert!(json["result"]["completed_capabilities"]
        .as_array()
        .unwrap()
        .iter()
        .any(|capability| capability["id"] == "export_demo_baseline"));
    assert!(json["result"]["missing_capabilities"]
        .as_array()
        .unwrap()
        .iter()
        .any(|capability| capability["id"] == "replacement_grade_cli"));
    assert!(json["result"]["missing_capabilities"]
        .as_array()
        .unwrap()
        .iter()
        .any(|capability| capability["id"] == "experimental_multimodal_runtime"));
    assert_eq!(json["result"]["promotion_decision"]["decision"], "promote");
    assert!(json["result"]["promotion_decision"]["blocked_by"]
        .as_array()
        .unwrap()
        .is_empty());
}

