#[test]
fn patch_review_summarizes_current_diff_without_applying_changes() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("foundry.sqlite");
    let target = temp.path().join("sample.txt");
    fs::write(&target, "alpha\n").unwrap();
    let git_init = std::process::Command::new("git")
        .arg("init")
        .current_dir(temp.path())
        .status()
        .expect("git init should run");
    assert!(git_init.success());
    let git_add = std::process::Command::new("git")
        .args(["add", "sample.txt"])
        .current_dir(temp.path())
        .status()
        .expect("git add should run");
    assert!(git_add.success());

    let planned = foundry()
        .current_dir(temp.path())
        .args([
            "--store",
            store.to_str().unwrap(),
            "plan",
            "--goal",
            "Demonstrate a Foundry-owned file patch review",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let planned_json: Value = serde_json::from_slice(&planned).unwrap();
    let workflow_id = planned_json["workflow_id"].as_str().unwrap();

    foundry()
        .current_dir(temp.path())
        .args([
            "--store",
            store.to_str().unwrap(),
            "patch",
            "plan",
            "--workflow",
            workflow_id,
            "--task",
            "task-001",
            "--intent",
            "Review the sample file diff",
            "--path",
            "sample.txt",
            "--origin",
            "test",
            "--output",
            "json",
        ])
        .assert()
        .success();

    fs::write(&target, "alpha\nbeta\n").unwrap();
    let before_review = fs::read(&target).unwrap();

    let output = foundry()
        .current_dir(temp.path())
        .args([
            "--store",
            store.to_str().unwrap(),
            "patch",
            "review",
            "--workflow",
            workflow_id,
            "--task",
            "task-001",
            "--path",
            "sample.txt",
            "--origin",
            "test",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();

    let after_review = fs::read(&target).unwrap();
    assert_eq!(
        before_review, after_review,
        "patch review must not edit source files"
    );

    let json: Value = serde_json::from_slice(&output).unwrap();
    assert_eq!(json["schema_version"], "foundry.patch_review.v1");
    assert_eq!(json["status"], "patch_review_ready");
    assert_eq!(json["workflow_id"], workflow_id);
    assert_eq!(json["task_id"], "task-001");
    assert_eq!(json["applies_changes"], false);
    assert_eq!(json["external_resources_mutated"], false);
    assert_eq!(json["requires_human_approval"], true);
    assert_eq!(json["summary"]["changed_path_count"], 1);
    assert_eq!(json["summary"]["diff_present"], true);
    assert_eq!(json["summary"]["diff_check_passed"], true);
    assert_eq!(
        json["summary"]["approval_recommendation"],
        "ready_for_human_review"
    );
    assert!(json["path_reviews"]
        .as_array()
        .unwrap()
        .iter()
        .any(|review| review["path"] == "sample.txt"
            && review["changed"] == true
            && review["diff_excerpt"].as_str().unwrap().contains("+beta")));
    assert!(json["artifact"]["path"]
        .as_str()
        .unwrap()
        .contains("attached-patch_review-"));
}

#[test]
fn patch_diff_builds_multi_file_navigation_without_applying_changes() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("foundry.sqlite");
    let first = temp.path().join("sample.txt");
    let second = temp.path().join("notes.txt");
    fs::write(&first, "alpha\nbravo\ncharlie\n").unwrap();
    fs::write(&second, "one\ntwo\nthree\n").unwrap();
    assert!(std::process::Command::new("git")
        .arg("init")
        .current_dir(temp.path())
        .status()
        .expect("git init should run")
        .success());
    assert!(std::process::Command::new("git")
        .args(["add", "sample.txt", "notes.txt"])
        .current_dir(temp.path())
        .status()
        .expect("git add should run")
        .success());
    assert!(std::process::Command::new("git")
        .args([
            "-c",
            "user.email=test@example.com",
            "-c",
            "user.name=Foundry Test",
            "commit",
            "-m",
            "initial",
        ])
        .current_dir(temp.path())
        .status()
        .expect("git commit should run")
        .success());

    let planned = foundry()
        .current_dir(temp.path())
        .args([
            "--store",
            store.to_str().unwrap(),
            "plan",
            "--goal",
            "Demonstrate multi-file diff navigation",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let workflow_id = serde_json::from_slice::<Value>(&planned).unwrap()["workflow_id"]
        .as_str()
        .unwrap()
        .to_string();

    fs::write(&first, "alpha\nbravo changed\ncharlie\n").unwrap();
    fs::write(&second, "one\ntwo changed\nthree\n").unwrap();

    let output = foundry()
        .current_dir(temp.path())
        .args([
            "--store",
            store.to_str().unwrap(),
            "patch",
            "diff",
            "--workflow",
            &workflow_id,
            "--task",
            "task-001",
            "--path",
            "sample.txt",
            "--path",
            "notes.txt",
            "--file-index",
            "1",
            "--hunk-index",
            "0",
            "--context-lines",
            "2",
            "--origin",
            "test",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();

    assert_eq!(
        fs::read_to_string(&first).unwrap(),
        "alpha\nbravo changed\ncharlie\n"
    );
    assert_eq!(
        fs::read_to_string(&second).unwrap(),
        "one\ntwo changed\nthree\n"
    );
    let json: Value = serde_json::from_slice(&output).unwrap();
    assert_eq!(json["schema_version"], "foundry.patch_diff.v1");
    assert_eq!(json["status"], "patch_diff_ready");
    assert_eq!(json["applies_changes"], false);
    assert_eq!(json["external_resources_mutated"], false);
    assert_eq!(json["summary"]["changed_file_count"], 2);
    assert_eq!(json["selection"]["selected_file_index"], 1);
    assert_eq!(json["selection"]["selected_hunk_index"], 0);
    assert_eq!(json["selection"]["selected_path"], "notes.txt");
    assert_eq!(json["navigation"]["has_previous_file"], true);
    assert_eq!(json["navigation"]["has_next_file"], false);
    assert!(json["files"].as_array().unwrap().len() >= 2);
    assert!(!json["files"][0]["hunks"].as_array().unwrap().is_empty());
    assert!(json["files"][1]["hunks"][0]["lines"]
        .as_array()
        .unwrap()
        .iter()
        .any(|line| line["kind"] == "addition" && line["content"] == "two changed"));
    assert!(json["artifact"]["path"]
        .as_str()
        .unwrap()
        .contains("attached-patch_diff-"));
}

#[test]
fn patch_apply_records_file_state_and_validation() {
    let temp = tempdir().unwrap();
    let store_path = temp.path().join("foundry.sqlite");
    let store = FoundryStore::open(&store_path).unwrap();
    let workflow_id = setup_test_workflow(&store);

    // Use empty validation commands to avoid recursive test execution.
    let report = foundry_core::patch::build_patch_apply(
        &store,
        &workflow_id,
        "task-001",
        vec!["Cargo.toml".to_string()],
        "test",
        None,
        Some(&[]),
    )
    .unwrap();

    assert_eq!(report.schema_version, "foundry.patch_apply.v1");
    assert_eq!(report.status, "patch_applied");
    assert_eq!(report.workflow_id, workflow_id);
    assert_eq!(report.task_id, "task-001");
    assert!(report
        .file_snapshots
        .iter()
        .any(|s| s.path == "Cargo.toml" && s.exists));
    assert!(report.validation.passed);
    assert!(!report.rollback_instructions.is_empty());
    assert!(report.artifact.is_some());
    assert!(report
        .artifact
        .as_ref()
        .unwrap()
        .path
        .contains("attached-patch_apply-"));
}

#[test]
fn patch_revert_records_proposal_without_restoring_files_automatically() {
    let temp = tempdir().unwrap();
    let store_path = temp.path().join("foundry.sqlite");
    let store = FoundryStore::open(&store_path).unwrap();
    let workflow_id = setup_test_workflow(&store);

    // Read original Cargo.toml content to verify revert restores it.
    let original_content = fs::read("Cargo.toml").unwrap();
    let original_sha256 = hex_sha256(&original_content);

    // Apply with no validation commands (fast in test context).
    let apply_report = foundry_core::patch::build_patch_apply(
        &store,
        &workflow_id,
        "task-001",
        vec!["Cargo.toml".to_string()],
        "test",
        None,
        Some(&[]),
    )
    .unwrap();

    assert_eq!(apply_report.status, "patch_applied");
    // The artifact path is relative to base_dir – resolve it to an absolute path.
    let apply_artifact_path = store
        .base_dir()
        .join(&apply_report.artifact.as_ref().unwrap().path);
    let apply_artifact_str = apply_artifact_path.to_str().unwrap().to_string();

    // Revert records a guarded rollback proposal by default; Foundry must not
    // run a destructive git checkout without an explicit human approval path.
    let revert_report = foundry_core::patch::build_patch_revert(
        &store,
        &workflow_id,
        "task-001",
        &apply_artifact_str,
        "test",
        Some(&[]),
    )
    .unwrap();

    assert_eq!(revert_report.schema_version, "foundry.patch_revert.v1");
    assert_eq!(revert_report.status, "patch_revert_proposed");
    assert_eq!(revert_report.workflow_id, workflow_id);
    assert_eq!(revert_report.task_id, "task-001");
    assert!(!revert_report.restore_executed);
    assert!(revert_report.requires_human_approval);
    assert!(revert_report
        .approval_command
        .as_ref()
        .unwrap()
        .contains("git checkout -- Cargo.toml"));
    assert!(revert_report.restored_snapshots.is_empty());
    assert!(revert_report.validation.commands.is_empty());
    assert!(revert_report.artifact.is_some());
    assert!(revert_report
        .artifact
        .as_ref()
        .unwrap()
        .path
        .contains("attached-patch_revert-"));

    // Verify file content is unchanged after round trip.
    let after_content = fs::read("Cargo.toml").unwrap();
    let after_sha256 = hex_sha256(&after_content);
    assert_eq!(
        original_sha256, after_sha256,
        "revert must restore original file content"
    );
}

#[test]
fn patch_restore_executes_git_restore_only_with_explicit_approval() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("foundry.sqlite");
    let target = temp.path().join("sample.txt");
    fs::write(&target, "alpha\n").unwrap();
    assert!(std::process::Command::new("git")
        .arg("init")
        .current_dir(temp.path())
        .status()
        .expect("git init should run")
        .success());
    assert!(std::process::Command::new("git")
        .args(["add", "sample.txt"])
        .current_dir(temp.path())
        .status()
        .expect("git add should run")
        .success());
    assert!(std::process::Command::new("git")
        .args([
            "-c",
            "user.email=test@example.com",
            "-c",
            "user.name=Foundry Test",
            "commit",
            "-m",
            "initial",
        ])
        .current_dir(temp.path())
        .status()
        .expect("git commit should run")
        .success());

    let planned = foundry()
        .current_dir(temp.path())
        .args([
            "--store",
            store.to_str().unwrap(),
            "plan",
            "--goal",
            "Demonstrate approved patch restore",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let workflow_id = serde_json::from_slice::<Value>(&planned).unwrap()["workflow_id"]
        .as_str()
        .unwrap()
        .to_string();

    fs::write(&target, "alpha\nbeta\n").unwrap();

    let apply_output = foundry()
        .current_dir(temp.path())
        .args([
            "--store",
            store.to_str().unwrap(),
            "patch",
            "apply",
            "--workflow",
            &workflow_id,
            "--task",
            "task-001",
            "--path",
            "sample.txt",
            "--origin",
            "test",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let apply_json: Value = serde_json::from_slice(&apply_output).unwrap();
    let apply_artifact = apply_json["artifact"]["path"].as_str().unwrap();
    let apply_artifact_path = if Path::new(apply_artifact).is_absolute() {
        apply_artifact.to_string()
    } else {
        temp.path()
            .join(apply_artifact)
            .to_string_lossy()
            .to_string()
    };

    let revert_output = foundry()
        .current_dir(temp.path())
        .args([
            "--store",
            store.to_str().unwrap(),
            "patch",
            "revert",
            "--workflow",
            &workflow_id,
            "--task",
            "task-001",
            "--apply-artifact",
            &apply_artifact_path,
            "--origin",
            "test",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let revert_json: Value = serde_json::from_slice(&revert_output).unwrap();
    let revert_artifact = revert_json["artifact"]["path"].as_str().unwrap();
    let revert_artifact_path = if Path::new(revert_artifact).is_absolute() {
        revert_artifact.to_string()
    } else {
        temp.path()
            .join(revert_artifact)
            .to_string_lossy()
            .to_string()
    };

    foundry()
        .current_dir(temp.path())
        .args([
            "--store",
            store.to_str().unwrap(),
            "patch",
            "restore",
            "--workflow",
            &workflow_id,
            "--task",
            "task-001",
            "--revert-artifact",
            &revert_artifact_path,
            "--approved-by",
            "tester",
            "--output",
            "json",
        ])
        .assert()
        .failure()
        .stderr(predicates::str::contains("--confirm-restore"));
    assert_eq!(fs::read_to_string(&target).unwrap(), "alpha\nbeta\n");

    let restore_output = foundry()
        .current_dir(temp.path())
        .args([
            "--store",
            store.to_str().unwrap(),
            "patch",
            "restore",
            "--workflow",
            &workflow_id,
            "--task",
            "task-001",
            "--revert-artifact",
            &revert_artifact_path,
            "--approved-by",
            "tester",
            "--confirm-restore",
            "--origin",
            "test",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();

    assert_eq!(fs::read_to_string(&target).unwrap(), "alpha\n");
    let json: Value = serde_json::from_slice(&restore_output).unwrap();
    assert_eq!(json["schema_version"], "foundry.patch_restore.v1");
    assert_eq!(json["status"], "patch_restored");
    assert_eq!(json["workflow_id"], workflow_id);
    assert_eq!(json["task_id"], "task-001");
    assert_eq!(json["restore_executed"], true);
    assert_eq!(json["requires_human_approval"], true);
    assert_eq!(json["approved_by"], "tester");
    assert!(json["restored_paths"]
        .as_array()
        .unwrap()
        .contains(&serde_json::json!("sample.txt")));
    assert_eq!(json["restore_command"]["status"], "passed");
    assert!(json["artifact"]["path"]
        .as_str()
        .unwrap()
        .contains("attached-patch_restore-"));
}

