#[test]
fn improve_candidates_measure_completed_repetitive_ai_history_without_reopening_task() {
    use foundry_core::graph::{self, ExecutorKind, TaskStatus};

    let temp = tempdir().unwrap();
    let store_path = temp.path().join("foundry.sqlite");
    let store = FoundryStore::open(&store_path).unwrap();
    let mut workflow = graph::create_workflow(foundry_core::intent::parse_intent(
        "Measure historical repeated AI cost without reopening completed work",
    ));
    workflow.status = "completed".to_string();
    workflow.tasks = vec![graph::task(
        "task-cost",
        "Calculate daily cost report",
        &[],
        &[],
        vec![],
        "deterministic cost JSON",
        (ExecutorKind::Ai, 2.0),
    )];
    workflow.tasks[0].status = TaskStatus::Completed;
    workflow.tasks[0]
        .work_item
        .goal_validation
        .definitively_ready = true;
    store.save_workflow(&workflow).unwrap();
    for estimated_usd in [0.4, 0.6] {
        store
            .record_event(
                &workflow.id,
                "executor_response_promoted",
                &serde_json::json!({
                    "task_id": "task-cost",
                    "response_status": "completed",
                    "cost": {
                        "estimated_usd": estimated_usd,
                        "tokens_in": 1000,
                        "tokens_out": 200
                    }
                }),
            )
            .unwrap();
    }
    drop(store);

    let output = foundry()
        .args([
            "--store",
            store_path.to_str().unwrap(),
            "improve",
            "candidates",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();

    let report: Value = serde_json::from_slice(&output).unwrap();
    let top = &report["candidates"][0];
    assert_eq!(top["workflow_id"], workflow.id);
    assert_eq!(
        top["cost_efficiency"]["repetitive_or_deterministic_ai_task_count"],
        0
    );
    assert_eq!(
        top["cost_efficiency"]["repetitive_or_deterministic_ai_cost_item_count"],
        1
    );
    assert_eq!(
        top["cost_efficiency"]["measured_repetitive_or_deterministic_ai_execution_count"],
        2
    );
    assert_eq!(
        top["cost_efficiency"]["measured_repetitive_or_deterministic_ai_cost_total_usd"],
        1.0
    );
    assert_eq!(
        top["cost_efficiency"]["measured_repetitive_or_deterministic_ai_cost_average_usd"],
        0.5
    );
    let item = &top["cost_efficiency"]["repetitive_or_deterministic_ai_cost_items"][0];
    assert_eq!(item["observed_execution_count"], 2);
    assert_eq!(item["observed_cost_average_per_execution_usd"], 0.5);
    assert_eq!(top["cost_efficiency"]["avoidable_estimated_cost_usd"], 0.0);
    assert!(!top["reasons"]
        .as_array()
        .unwrap()
        .iter()
        .any(|reason| reason["code"] == "avoidable_ai_cost"));
}

#[test]
fn improve_candidates_evaluate_attached_final_completion_audit() {
    use chrono::Utc;
    use foundry_core::graph::{self, ArtifactRecord, ExecutorKind};

    let temp = tempdir().unwrap();
    let store_path = temp.path().join("foundry.sqlite");
    let artifact_path = temp
        .path()
        .join("artifacts/demo/final_completion_audit.json");
    fs::create_dir_all(artifact_path.parent().unwrap()).unwrap();
    fs::write(
        &artifact_path,
        serde_json::to_vec_pretty(&serde_json::json!({
            "schema_version": "foundry.final_completion_audit.v1",
            "status": "passed",
            "goal_fully_satisfied": true,
            "evidence": [
                {
                    "criterion": "User-facing deliverable is verified",
                    "status": "passed",
                    "artifact_refs": ["artifacts/demo/report.md"],
                    "summary": "The final output has been audited."
                }
            ],
            "missing_criteria": [],
            "open_items": []
        }))
        .unwrap(),
    )
    .unwrap();

    let store = FoundryStore::open(&store_path).unwrap();
    let mut workflow = graph::create_workflow(foundry_core::intent::parse_intent(
        "Deliver final workflow result with a final completion audit.",
    ));
    workflow.status = "running".to_string();
    workflow.tasks = vec![
        graph::task(
            "task-left",
            "Support task left pending",
            &[],
            &[],
            vec![],
            "support evidence",
            (ExecutorKind::Command, 0.0002),
        ),
        graph::task(
            "task-right",
            "Second support task left pending",
            &[],
            &[],
            vec![],
            "support evidence",
            (ExecutorKind::Command, 0.0002),
        ),
    ];
    workflow.artifacts.push(ArtifactRecord {
        id: "artifact-final-audit".to_string(),
        kind: "final_completion_audit".to_string(),
        path: "artifacts/demo/final_completion_audit.json".to_string(),
        sha256: hex_sha256(&fs::read(&artifact_path).unwrap()),
        tags: Vec::new(),
        created_at: Utc::now(),
        lineage: None,
    });
    store.save_workflow(&workflow).unwrap();
    drop(store);

    let output = foundry()
        .args([
            "--store",
            store_path.to_str().unwrap(),
            "improve",
            "candidates",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();

    let report: Value = serde_json::from_slice(&output).unwrap();
    let top = &report["candidates"][0];
    assert_eq!(top["workflow_id"], workflow.id);
    assert_eq!(top["outcome_status"]["status"], "final_outcome_verified");
    assert_eq!(
        top["outcome_status"]["final_completion_audit_present"],
        true
    );
    assert_eq!(
        top["outcome_status"]["final_completion_audit_evaluated"],
        true
    );
    assert_eq!(top["outcome_status"]["final_completion_audit_passed"], true);
    assert!(!top["reasons"]
        .as_array()
        .unwrap()
        .iter()
        .any(|reason| reason["code"] == "missing_final_outcome_audit"));
    assert!(!top["reasons"]
        .as_array()
        .unwrap()
        .iter()
        .any(|reason| reason["code"] == "parallelization_opportunity"));
    assert!(top["reasons"]
        .as_array()
        .unwrap()
        .iter()
        .any(|reason| reason["code"] == "post_final_verification_cleanup"));
    assert!(top["score"].as_i64().unwrap() < 45);
    assert_eq!(
        top["recommended_action"],
        "refresh_final_delivery_package_if_needed"
    );
}

#[test]
fn improve_candidates_deprioritize_final_verified_workflows_below_unfinished_outcomes() {
    use chrono::Utc;
    use foundry_core::graph::{self, ArtifactRecord, ExecutorKind, TaskStatus};

    let temp = tempdir().unwrap();
    let store_path = temp.path().join("foundry.sqlite");
    let final_audit_path = temp
        .path()
        .join("artifacts/verified/final_completion_audit.json");
    fs::create_dir_all(final_audit_path.parent().unwrap()).unwrap();
    fs::write(
        &final_audit_path,
        serde_json::to_vec_pretty(&serde_json::json!({
            "schema_version": "foundry.final_completion_audit.v1",
            "status": "passed",
            "goal_fully_satisfied": true,
            "evidence": [{
                "criterion": "Demo report delivered",
                "status": "passed",
                "artifact_refs": ["artifacts/verified/demo-report.md"],
                "summary": "The demo report is verified."
            }],
            "missing_criteria": [],
            "open_items": []
        }))
        .unwrap(),
    )
    .unwrap();
    let report_path = temp.path().join("artifacts/missing/demo-report.md");
    fs::create_dir_all(report_path.parent().unwrap()).unwrap();
    fs::write(&report_path, "# Demo report\n").unwrap();

    let store = FoundryStore::open(&store_path).unwrap();
    let mut verified = graph::create_workflow(foundry_core::intent::parse_intent(
        "Deliver partner demo report with final audit.",
    ));
    verified.status = "running".to_string();
    verified.intent.deliverables = vec!["Demo report".to_string()];
    verified.tasks = vec![
        graph::task(
            "task-left",
            "Support task left pending",
            &[],
            &[],
            vec![],
            "support evidence",
            (ExecutorKind::Command, 0.0002),
        ),
        graph::task(
            "task-right",
            "Second support task left pending",
            &[],
            &[],
            vec![],
            "support evidence",
            (ExecutorKind::Command, 0.0002),
        ),
    ];
    verified.artifacts.push(ArtifactRecord {
        id: "artifact-final-audit".to_string(),
        kind: "final_completion_audit".to_string(),
        path: "artifacts/verified/final_completion_audit.json".to_string(),
        sha256: hex_sha256(&fs::read(&final_audit_path).unwrap()),
        tags: Vec::new(),
        created_at: Utc::now(),
        lineage: None,
    });
    store.save_workflow(&verified).unwrap();
    store
        .record_event(
            &verified.id,
            "executor_response_promoted",
            &serde_json::json!({
                "task_id": "task-left",
                "response_status": "needs_retry",
                "summary": "historical retry before final audit"
            }),
        )
        .unwrap();

    let mut missing_audit = graph::create_workflow(foundry_core::intent::parse_intent(
        "Deliver partner demo report. Critério Final: only complete when the demo report is audited.",
    ));
    missing_audit.status = "running".to_string();
    missing_audit.intent.deliverables = vec!["Demo report".to_string()];
    missing_audit.tasks = vec![
        graph::task(
            "task-report",
            "Demo report",
            &[],
            &[],
            vec![],
            "Demo report",
            (ExecutorKind::Command, 0.0002),
        ),
        graph::task(
            "task-support-left",
            "Support cleanup left pending",
            &[],
            &[],
            vec![],
            "support evidence",
            (ExecutorKind::Command, 0.0002),
        ),
        graph::task(
            "task-support-right",
            "Support cleanup right pending",
            &[],
            &[],
            vec![],
            "support evidence",
            (ExecutorKind::Command, 0.0002),
        ),
    ];
    missing_audit.tasks[0].status = TaskStatus::Completed;
    missing_audit.tasks[0]
        .work_item
        .goal_validation
        .definitively_ready = true;
    missing_audit.artifacts.push(ArtifactRecord {
        id: "artifact-demo-report".to_string(),
        kind: "markdown_report".to_string(),
        path: "artifacts/missing/demo-report.md".to_string(),
        sha256: hex_sha256(&fs::read(&report_path).unwrap()),
        tags: Vec::new(),
        created_at: Utc::now(),
        lineage: None,
    });
    store.save_workflow(&missing_audit).unwrap();
    drop(store);

    let output = foundry()
        .args([
            "--store",
            store_path.to_str().unwrap(),
            "improve",
            "candidates",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();

    let report: Value = serde_json::from_slice(&output).unwrap();
    let candidates = report["candidates"].as_array().unwrap();
    assert_eq!(
        candidates[0]["workflow_id"],
        missing_audit.id,
        "candidates: {}",
        serde_json::to_string_pretty(&report["candidates"]).unwrap()
    );
    assert_eq!(
        candidates[0]["outcome_status"]["status"],
        "needs_final_outcome_audit"
    );
    assert!(candidates[0]["reasons"]
        .as_array()
        .unwrap()
        .iter()
        .any(|reason| reason["code"] == "missing_final_outcome_audit"));
    assert!(candidates[0]["reasons"]
        .as_array()
        .unwrap()
        .iter()
        .any(|reason| reason["code"] == "parallelization_opportunity"));
    assert_eq!(
        candidates[0]["recommended_action"],
        "produce_and_package_final_user_outcome"
    );
    let verified_candidate = candidates
        .iter()
        .find(|candidate| candidate["workflow_id"] == verified.id)
        .unwrap();
    assert_eq!(
        verified_candidate["outcome_status"]["status"],
        "final_outcome_verified"
    );
    assert!(
        verified_candidate["score"].as_i64().unwrap() < candidates[0]["score"].as_i64().unwrap()
    );
    assert!(!verified_candidate["reasons"]
        .as_array()
        .unwrap()
        .iter()
        .any(|reason| reason["code"] == "rework_loop_signal"));
}

#[test]
fn improve_candidates_recommend_deliverable_repair_for_support_only_workflows() {
    use foundry_core::graph::{self, ExecutorKind};

    let temp = tempdir().unwrap();
    let store_path = temp.path().join("foundry.sqlite");
    let store = FoundryStore::open(&store_path).unwrap();
    let mut workflow = graph::create_workflow(foundry_core::intent::parse_intent(
        "Generate an internal atomic task graph for tracking.",
    ));
    workflow.status = "running".to_string();
    workflow.intent.deliverables = vec!["Atomic task graph".to_string()];
    workflow.tasks = vec![graph::task(
        "task-graph",
        "Build atomic task graph",
        &[],
        &[],
        vec![],
        "atomic task graph",
        (ExecutorKind::Command, 0.0002),
    )];
    store.save_workflow(&workflow).unwrap();
    drop(store);

    let output = foundry()
        .args([
            "--store",
            store_path.to_str().unwrap(),
            "improve",
            "candidates",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();

    let report: Value = serde_json::from_slice(&output).unwrap();
    let top = &report["candidates"][0];
    assert_eq!(top["workflow_id"], workflow.id);
    assert_eq!(top["outcome_status"]["status"], "support_only");
    assert!(top["reasons"]
        .as_array()
        .unwrap()
        .iter()
        .any(|reason| reason["code"] == "support_only_output_risk"));
    assert_eq!(
        top["recommended_action"],
        "update_goal_or_tasks_with_user_facing_deliverables"
    );
    let commands = top["suggested_commands"].as_array().unwrap();
    assert!(commands.iter().any(|command| {
        command.as_array().unwrap()
            == &vec![
                Value::String("foundry".to_string()),
                Value::String("workflow".to_string()),
                Value::String("update-goal".to_string()),
                Value::String("--workflow".to_string()),
                Value::String(workflow.id.clone()),
                Value::String("--goal".to_string()),
                Value::String("<goal with explicit user-facing deliverables>".to_string()),
                Value::String("--origin".to_string()),
                Value::String("foundry_cli".to_string()),
                Value::String("--output".to_string()),
                Value::String("json".to_string()),
            ]
    }));
    assert!(commands.iter().any(|command| {
        command.as_array().unwrap()
            == &vec![
                Value::String("foundry".to_string()),
                Value::String("status".to_string()),
                Value::String("--workflow".to_string()),
                Value::String(workflow.id.clone()),
                Value::String("--output".to_string()),
                Value::String("json".to_string()),
            ]
    }));
    assert!(!commands.iter().any(|command| command
        .as_array()
        .unwrap()
        .contains(&Value::String("final-package".to_string()))));
    assert!(!commands.iter().any(|command| command
        .as_array()
        .unwrap()
        .contains(&Value::String("handoff".to_string()))));
}

