#[test]
fn workflow_goals_can_be_mutated_during_runtime_with_origin_trace() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("foundry.sqlite");
    let output = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "plan",
            "--goal",
            "Create a mutable workflow",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let json: Value = serde_json::from_slice(&output).unwrap();
    let workflow_id = json["workflow_id"].as_str().unwrap();

    let update_output = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "workflow",
            "update-goal",
            "--workflow",
            workflow_id,
            "--goal",
            "Create a mutable workflow with Codex/OpenCode human interface",
            "--origin",
            "codex",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();

    let update: Value = serde_json::from_slice(&update_output).unwrap();
    assert_eq!(update["status"], "workflow_goal_updated");
    assert_eq!(update["origin"], "codex");
    assert_eq!(
        update["new_goal"],
        "Create a mutable workflow with Codex/OpenCode human interface"
    );
    assert!(update["revision"].as_u64().unwrap() >= 1);

    let status = foundry()
        .current_dir(temp.path())
        .args([
            "--store",
            store.to_str().unwrap(),
            "status",
            "--workflow",
            workflow_id,
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let status_json: Value = serde_json::from_slice(&status).unwrap();
    assert_eq!(
        status_json["goal"],
        "Create a mutable workflow with Codex/OpenCode human interface"
    );
    assert_eq!(status_json["revisions"].as_array().unwrap().len(), 1);
    assert_eq!(status_json["revisions"][0]["origin"], "codex");
}

#[test]
fn workflow_goal_update_reparses_intent_deliverables_and_outcome_gate() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("foundry.sqlite");
    let started = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "request",
            "start",
            "--goal",
            "Generate internal workflow support artifacts",
            "--origin",
            "codex",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let started_json: Value = serde_json::from_slice(&started).unwrap();
    let workflow_id = started_json["workflow_id"].as_str().unwrap();
    let run_id = started_json["run_id"].as_str().unwrap();

    let before = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "request",
            "status",
            "--run",
            run_id,
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let before_json: Value = serde_json::from_slice(&before).unwrap();
    assert_eq!(before_json["outcome_status"]["status"], "support_only");

    let update_output = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "workflow",
            "update-goal",
            "--workflow",
            workflow_id,
            "--goal",
            "Implementar o Foundry Core e entregar relatório final em Markdown, enviando o relatório no Telegram",
            "--origin",
            "codex",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let update_json: Value = serde_json::from_slice(&update_output).unwrap();
    assert_eq!(update_json["status"], "workflow_goal_updated");
    assert!(
        update_json["new_deliverable_count"].as_u64().unwrap()
            > update_json["previous_deliverable_count"].as_u64().unwrap()
    );
    let added = update_json["added_deliverables"].as_array().unwrap();
    assert!(added.contains(&Value::String("Telegram notification evidence".to_string())));
    assert!(added.contains(&Value::String("final Markdown report".to_string())));
    assert!(added.contains(&Value::String(
        "verified user-facing final outcome".to_string()
    )));

    let after = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "request",
            "status",
            "--run",
            run_id,
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let after_json: Value = serde_json::from_slice(&after).unwrap();
    assert_eq!(
        after_json["outcome_status"]["status"],
        "needs_user_delivery_evidence"
    );
    assert!(
        after_json["outcome_status"]["user_facing_deliverable_count"]
            .as_u64()
            .unwrap()
            >= 3
    );
    assert!(after_json["outcome_status"]["deliverables"]
        .as_array()
        .unwrap()
        .iter()
        .any(|deliverable| deliverable["name"] == "final Markdown report"
            && deliverable["kind"] == "user_facing"));
}

