#[test]
fn workflow_artifacts_can_be_attached_during_runtime_from_codex_or_opencode() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("foundry.sqlite");
    let artifact = temp.path().join("runtime-note.md");
    fs::write(
        &artifact,
        "# Runtime note\n\nArtifact attached while workflow is running.\n",
    )
    .unwrap();
    let output = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "plan",
            "--goal",
            "Create runtime artifact mutation",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let json: Value = serde_json::from_slice(&output).unwrap();
    let workflow_id = json["workflow_id"].as_str().unwrap();

    let attach_output = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "workflow",
            "attach-artifact",
            "--workflow",
            workflow_id,
            "--path",
            artifact.to_str().unwrap(),
            "--kind",
            "runtime_note",
            "--origin",
            "opencode",
            "--tag",
            "crm",
            "--tag",
            "proposal",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();

    let attach: Value = serde_json::from_slice(&attach_output).unwrap();
    assert_eq!(attach["status"], "artifact_attached");
    assert_eq!(attach["origin"], "opencode");
    assert_eq!(attach["artifact"]["kind"], "runtime_note");
    assert!(attach["artifact"]["sha256"].as_str().unwrap().len() >= 64);
    assert!(attach["artifact"]["tags"]
        .as_array()
        .unwrap()
        .contains(&serde_json::json!("crm")));
    assert!(attach["artifact"]["tags"]
        .as_array()
        .unwrap()
        .contains(&serde_json::json!("proposal")));
    assert!(attach["artifact"]["tags"]
        .as_array()
        .unwrap()
        .contains(&serde_json::json!("runtime_note")));
    assert!(attach["artifact"]["tags"]
        .as_array()
        .unwrap()
        .contains(&serde_json::json!("opencode")));

    let artifacts = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "artifacts",
            "--workflow",
            workflow_id,
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let artifacts_json: Value = serde_json::from_slice(&artifacts).unwrap();
    assert!(artifacts_json["artifacts"]
        .as_array()
        .unwrap()
        .iter()
        .any(|item| item["path"].as_str().unwrap().contains("runtime-note.md")));
    let listed_artifact = artifacts_json["artifacts"]
        .as_array()
        .unwrap()
        .iter()
        .find(|item| item["path"].as_str().unwrap().contains("runtime-note.md"))
        .unwrap();
    assert!(listed_artifact["tags"]
        .as_array()
        .unwrap()
        .contains(&serde_json::json!("crm")));
    assert!(listed_artifact["tags"]
        .as_array()
        .unwrap()
        .contains(&serde_json::json!("proposal")));

    let status = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "status",
            "--workflow",
            workflow_id,
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let status_json: Value = serde_json::from_slice(&status).unwrap();
    assert!(status_json["artifacts"]
        .as_array()
        .unwrap()
        .iter()
        .any(|item| item["tags"]
            .as_array()
            .unwrap()
            .contains(&serde_json::json!("crm"))));
}

#[test]
fn self_run_dry_run_creates_bounded_self_evolution_workflow_and_artifacts() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("foundry.sqlite");
    let repo = temp.path().join("repo");
    fs::create_dir_all(&repo).unwrap();
    fs::write(repo.join("README.md"), "# Repo\n").unwrap();

    let output = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "self",
            "run",
            "--repo",
            repo.to_str().unwrap(),
            "--until",
            "2999-01-01T00:00:00-03:00",
            "--max-cycles",
            "1",
            "--executor",
            "codex",
            "--executor",
            "opencode",
            "--dry-run",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();

    let json: Value = serde_json::from_slice(&output).unwrap();
    assert_eq!(json["status"], "planned");
    assert!(json["run_id"].as_str().unwrap().starts_with("run_"));
    assert_eq!(json["stop_at"], "2999-01-01T00:00:00-03:00");
    assert_eq!(json["executors"], serde_json::json!(["codex", "opencode"]));
    assert!(json["workflow_id"].as_str().unwrap().starts_with("wf_"));
    assert!(json["cycle_reports"].as_array().unwrap().len() == 1);
    let prompt_path = temp
        .path()
        .join(json["cycle_reports"][0]["prompt_path"].as_str().unwrap());
    assert!(prompt_path.exists());
    let prompt = fs::read_to_string(prompt_path).unwrap();
    assert!(prompt.contains("Improve Foundry Core"));
    assert!(prompt.contains("Codex/OpenCode"));
    assert!(prompt.contains("Personality/Soul Routing"));
    assert!(prompt.contains("Codex handles developer/personality instructions"));
    assert!(prompt.contains("Paperclip models soul, voice, tone or persona"));
    assert!(prompt.contains("auditable in lineage and validation-gated"));
    assert!(prompt.contains("cargo test"));
    assert!(prompt.contains("Do not mutate external Docker/Kubernetes/Knative resources"));
}

#[test]
fn self_run_persists_internal_recurring_loop_status_and_next_goal_decision() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("foundry.sqlite");
    let repo = temp.path().join("repo");
    fs::create_dir_all(&repo).unwrap();
    fs::write(repo.join("README.md"), "# Repo\n").unwrap();

    let output = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "self",
            "run",
            "--repo",
            repo.to_str().unwrap(),
            "--until",
            "2999-01-01T00:00:00-03:00",
            "--max-cycles",
            "1",
            "--sleep-seconds",
            "180",
            "--executor",
            "codex",
            "--dry-run",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();

    let json: Value = serde_json::from_slice(&output).unwrap();
    assert_eq!(
        json["internal_loop"]["schema_version"],
        "foundry.self_evolution.loop.v1"
    );
    assert!(
        json["internal_loop"]["loop_count"].as_u64().unwrap() > 0,
        "self-evolution must not have loop_count == 0"
    );
    assert_eq!(json["internal_loop"]["sleep_seconds"], 180);
    assert_eq!(
        json["internal_loop"]["sleep_policy"],
        "rest_between_iterations"
    );
    assert!(
        matches!(
            json["internal_loop"]["loop_control_kind"].as_str().unwrap(),
            "while_until" | "infinite_recurring_subflow"
        ),
        "self-evolution loop must use a persisted recurring loop primitive"
    );
    assert_eq!(
        json["internal_loop"]["execution_shape"],
        "ordinary_foundry_workflow_internal_recurring_loop"
    );
    assert_eq!(
        json["internal_loop"]["next_goal_decision"]["schema_version"],
        "foundry.self_evolution.next_goal_decision.v1"
    );
    assert_eq!(
        json["internal_loop"]["next_goal_decision"]["selected_goal"],
        "Make the Product/PM CLI-TUI the main entry point for human-guided product/workflow creation."
    );
    assert!(json["internal_loop"]["next_goal_decision"]["rationale"]
        .as_str()
        .unwrap()
        .contains("business"));
    assert!(
        json["internal_loop"]["next_goal_decision"]["workflow_revision"]
            .as_u64()
            .unwrap()
            > 0
    );

    let workflow_id = json["workflow_id"].as_str().unwrap();
    let inspect_output = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "inspect",
            workflow_id,
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let inspect_json: Value = serde_json::from_slice(&inspect_output).unwrap();
    let loop_node = inspect_json["nodes"]
        .as_array()
        .unwrap()
        .iter()
        .find(|node| {
            node["expected_output"]
                .as_str()
                .is_some_and(|output| output.contains("next goal decision"))
        })
        .expect("self-evolution workflow should have a persisted loop_control node");
    assert!(matches!(
        loop_node["loop_control"]["kind"].as_str().unwrap(),
        "while_until" | "infinite_recurring_subflow"
    ));
    assert_eq!(
        loop_node["loop_control"]["subflow_mode"],
        "ordinary_foundry_workflow"
    );
    assert!(loop_node["expected_output"]
        .as_str()
        .unwrap()
        .contains("next goal decision"));
}

