#[test]
fn self_run_falls_back_to_agy_before_opencode_if_previous_executor_fails() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("foundry.sqlite");
    let repo = temp.path().join("repo");
    fs::create_dir_all(&repo).unwrap();
    let status = std::process::Command::new("git")
        .arg("init")
        .arg(&repo)
        .status()
        .expect("git init should succeed");
    assert!(status.success());
    configure_test_git_identity(&repo);
    fs::write(repo.join("README.md"), "# repo\n").unwrap();

    let executors_dir = temp.path().join("bin");
    fs::create_dir_all(&executors_dir).unwrap();

    write_fake_executor(
        &executors_dir,
        "codex",
        "#!/bin/sh\nif [ \"$1\" = \"--version\" ]; then printf 'codex 1.0\\n'; exit 0; fi\nexit 1\n",
    );
    write_fake_executor(
        &executors_dir,
        "agy",
        "#!/bin/sh\nif [ \"$1\" = \"--version\" ]; then printf 'agy 1.0\\n'; exit 0; fi\nif [ \"$1\" = \"--print\" ]; then printf 'ok from agy\\n'; exit 0; fi\nprintf 'ok from agy\\n'\nexit 0\n",
    );
    write_fake_executor(&executors_dir, "opencode", "#!/bin/sh\nexit 0\n");

    let old_path = std::env::var("PATH").unwrap_or_else(|_| "".to_string());
    let path = format!("{}:{}", executors_dir.display(), old_path);

    let output = foundry()
        .env("PATH", &path)
        .args([
            "--store",
            store.to_str().unwrap(),
            "self",
            "run",
            "--repo",
            repo.to_str().unwrap(),
            "--until",
            "2999-01-01T00:00:00-03:00",
            "--max-cycles",
            "1",
            "--validation-command",
            "true",
            "--skip-self-update",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();

    let json: Value = serde_json::from_slice(&output).unwrap();
    let cycle_report = &json["cycle_reports"][0];
    assert_eq!(cycle_report["requested_executor"], "codex");
    assert_eq!(cycle_report["executor"], "agy");
    assert_eq!(
        cycle_report["executor_fallbacks"],
        serde_json::json!(["agy", "opencode"])
    );
    let attempts = cycle_report["executor_attempts"].as_array().unwrap();
    assert_eq!(attempts.len(), 2);
    assert_eq!(attempts[0]["executor"], "codex");
    assert_eq!(attempts[0]["status"], "failed");
    assert_eq!(attempts[0]["local"], false);
    assert_eq!(attempts[0]["provider"], "openai");
    assert!(attempts[0]["model"].is_null());
    assert!(attempts[0]["next_fallback_reason"]
        .as_str()
        .unwrap()
        .contains("selected as first quota-aware candidate"));
    assert_eq!(attempts[1]["executor"], "agy");
    assert_eq!(attempts[1]["status"], "completed");
    assert_eq!(attempts[1]["provider"], "antigravity");
    assert_eq!(attempts[1]["model"], "agy-default");
    assert!(attempts[1]["next_fallback_reason"]
        .as_str()
        .unwrap()
        .contains("selected after an earlier quota-aware executor attempt failed"));
}

#[test]
fn self_run_keeps_request_active_between_multiple_cycles() {
    let temp = tempdir().unwrap();
    let store_path = temp.path().join("foundry.sqlite");
    let repo = temp.path().join("repo");
    fs::create_dir_all(&repo).unwrap();
    let status = std::process::Command::new("git")
        .arg("init")
        .arg(&repo)
        .status()
        .expect("git init should succeed");
    assert!(status.success());
    configure_test_git_identity(&repo);
    fs::write(repo.join("README.md"), "# repo\n").unwrap();

    let executors_dir = temp.path().join("bin");
    fs::create_dir_all(&executors_dir).unwrap();
    write_fake_executor(
        &executors_dir,
        "codex",
        "#!/bin/sh\nif [ \"$1\" = \"--version\" ]; then printf 'codex 1.0\\n'; exit 0; fi\nprintf 'ok from codex\\n'\nexit 0\n",
    );

    let old_path = std::env::var("PATH").unwrap_or_else(|_| "".to_string());
    let path = format!("{}:{}", executors_dir.display(), old_path);
    let output = foundry()
        .env("PATH", path)
        .args([
            "--store",
            store_path.to_str().unwrap(),
            "self",
            "run",
            "--repo",
            repo.to_str().unwrap(),
            "--until",
            "2999-01-01T00:00:00-03:00",
            "--max-cycles",
            "2",
            "--sleep-seconds",
            "0",
            "--executor",
            "codex",
            "--validation-command",
            "true",
            "--skip-self-update",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();

    let json: Value = serde_json::from_slice(&output).unwrap();
    assert_eq!(json["status"], "completed");
    assert_eq!(json["cycle_reports"].as_array().unwrap().len(), 2);
    assert_eq!(json["cycle_reports"][0]["cycle"], 1);
    assert_eq!(json["cycle_reports"][1]["cycle"], 2);
    assert!(json["cycle_reports"]
        .as_array()
        .unwrap()
        .iter()
        .all(|cycle| cycle["validation_passed"] == true));

    let store = FoundryStore::open(&store_path).unwrap();
    let run_id = json["run_id"].as_str().unwrap();
    let workflow_id = json["workflow_id"].as_str().unwrap();
    let status = foundry_core::request::load_request_status(&store, run_id).unwrap();
    assert_eq!(status.status, "completed");
    assert_eq!(status.workflow_status, "completed");
    assert_eq!(
        store
            .load_workflow_events(workflow_id)
            .unwrap()
            .iter()
            .filter(|event| event.kind == "async_request_heartbeat")
            .count(),
        4
    );
}

