#[test]
fn self_run_uses_latest_self_evolution_goal_instead_of_longest_goal() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("foundry.sqlite");
    let repo = temp.path().join("repo");
    fs::create_dir_all(&repo).unwrap();
    let base_goal =
        "Improve Foundry Core autonomously with bounded executor cycles, validation gates, artifacts and changelog";
    let terminal_goal = format!(
        "{base_goal}. Stopping rule: when Foundry has a validated lean/balanced/strict mode boundary, a measurable overhead ledger, and an automated self-evolution decision gate that can reject or stop cycles whose expected value is lower than orchestration cost, the self-evolution loop should mark the terminal goal reached, stop proposing new architecture by default, avoid further interaction, and only resume if a human gives a new explicit goal."
    );
    let latest_goal = format!(
        "{base_goal}. New explicit human goal: prioritize MCP workflow invocation, reusable Codex/OpenCode skills, async agent handoff with run_id, bounded context contracts and validation artifacts."
    );

    let old_output = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "plan",
            "--goal",
            base_goal,
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let old_plan: Value = serde_json::from_slice(&old_output).unwrap();
    let old_workflow_id = old_plan["workflow_id"].as_str().unwrap();

    foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "workflow",
            "update-goal",
            "--workflow",
            old_workflow_id,
            "--origin",
            "codex",
            "--goal",
            &terminal_goal,
            "--output",
            "json",
        ])
        .assert()
        .success();

    foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "plan",
            "--goal",
            &latest_goal,
            "--output",
            "json",
        ])
        .assert()
        .success();

    let self_output = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "self",
            "run",
            "--repo",
            repo.to_str().unwrap(),
            "--until",
            "2999-01-01T00:00:00-03:00",
            "--max-cycles",
            "1",
            "--mode",
            "balanced",
            "--dry-run",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();

    let json: Value = serde_json::from_slice(&self_output).unwrap();
    assert_eq!(json["status"], "planned");
    assert_eq!(json["decision_gate"]["decision"], "run_cycle");

    let prompt_path = json["cycle_reports"][0]["prompt_path"].as_str().unwrap();
    let prompt = fs::read_to_string(temp.path().join(prompt_path)).unwrap();
    assert!(prompt.contains(&latest_goal));
    assert!(!prompt.contains("terminal self-evolution goal is already satisfied"));
}

