#[test]
fn task_lease_prevents_two_executors_from_acquiring_same_task() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("foundry.sqlite");
    let output = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "plan",
            "--goal",
            "Run async task leasing for multiple executors",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let json: Value = serde_json::from_slice(&output).unwrap();
    let workflow_id = json["workflow_id"].as_str().unwrap();
    let task_id = json["tasks"][0]["id"].as_str().unwrap();

    let acquired = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "task",
            "acquire",
            "--workflow",
            workflow_id,
            "--task",
            task_id,
            "--executor",
            "codex",
            "--ttl-seconds",
            "600",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let acquired_json: Value = serde_json::from_slice(&acquired).unwrap();
    assert_eq!(acquired_json["status"], "lease_acquired");
    assert_eq!(acquired_json["allowed"], true);
    assert_eq!(acquired_json["lease"]["executor"], "codex");
    assert_eq!(acquired_json["lease"]["workflow_id"], workflow_id);
    assert_eq!(acquired_json["lease"]["task_id"], task_id);

    let conflict = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "task",
            "acquire",
            "--workflow",
            workflow_id,
            "--task",
            task_id,
            "--executor",
            "opencode",
            "--ttl-seconds",
            "600",
            "--output",
            "json",
        ])
        .assert()
        .failure()
        .get_output()
        .stdout
        .clone();
    let conflict_json: Value = serde_json::from_slice(&conflict).unwrap();
    assert_eq!(conflict_json["status"], "lease_conflict");
    assert_eq!(conflict_json["allowed"], false);
    assert_eq!(conflict_json["current_lease"]["executor"], "codex");

    foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "task",
            "release",
            "--workflow",
            workflow_id,
            "--task",
            task_id,
            "--lease",
            acquired_json["lease"]["lease_id"].as_str().unwrap(),
            "--executor",
            "codex",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .stdout(predicates::str::contains("lease_released"));

    foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "task",
            "acquire",
            "--workflow",
            workflow_id,
            "--task",
            task_id,
            "--executor",
            "opencode",
            "--ttl-seconds",
            "600",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .stdout(predicates::str::contains("\"executor\": \"opencode\""));
}

#[test]
fn task_handoff_packet_acquires_lease_and_wraps_strict_context_for_ready_executor() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("foundry.sqlite");
    persist_ready_executor_state(&store, "codex");
    persist_ready_executor_state(&store, "opencode");
    let output = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "plan",
            "--goal",
            "Handoff",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let json: Value = serde_json::from_slice(&output).unwrap();
    let workflow_id = json["workflow_id"].as_str().unwrap();
    let task_id = json["tasks"][0]["id"].as_str().unwrap();

    let handoff = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "task",
            "handoff",
            "--workflow",
            workflow_id,
            "--task",
            task_id,
            "--executor",
            "codex",
            "--ttl-seconds",
            "600",
            "--budget",
            "1200",
            "--view",
            "full",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let handoff_json: Value = serde_json::from_slice(&handoff).unwrap();
    assert_eq!(handoff_json["status"], "handoff_ready");
    assert_eq!(handoff_json["allowed"], true);
    assert_eq!(handoff_json["workflow_id"], workflow_id);
    assert_eq!(handoff_json["task_id"], task_id);
    assert_eq!(handoff_json["selected_executor"], "codex");
    assert_eq!(handoff_json["task_executor"], "command");
    assert_eq!(handoff_json["context"]["handoff_ready"], true);
    assert_eq!(handoff_json["context"]["handoff_status"], "ready");

    let packet = &handoff_json["packet"];
    assert_eq!(packet["schema_version"], "foundry.executor_handoff.v9");
    assert_eq!(packet["workflow_id"], workflow_id);
    assert_eq!(packet["task_id"], task_id);
    assert_eq!(packet["selected_executor"], "codex");
    assert_eq!(packet["task_executor"], "command");
    assert_eq!(packet["lease_required"], true);
    assert_eq!(packet["lease_status"], "lease_acquired");
    assert_eq!(
        packet["lease_id"],
        handoff_json["lease"]["lease_id"].as_str().unwrap()
    );
    assert_eq!(packet["context_schema_version"], "foundry.context.v30");
    assert_eq!(
        packet["context_sha256"],
        handoff_json["context"]["context_sha256"]
    );
    assert_eq!(
        packet["context_routing_fingerprint_schema_version"],
        "foundry.context.routing_fingerprint.v2"
    );
    assert_eq!(
        packet["context_routing_cache_key"],
        handoff_json["context"]["routing_fingerprint"]["cache_key"]
    );
    assert_eq!(
        packet["context_routing_cache_key"].as_str().unwrap().len(),
        64
    );
    assert_eq!(
        packet["context_routing_lineage_sha256"],
        handoff_json["context"]["routing_fingerprint"]["lineage_sha256"]
    );
    assert_eq!(
        packet["context_bytes"],
        handoff_json["context"]["context_bytes"]
    );
    assert_eq!(packet["handoff_ready"], true);
    assert_eq!(packet["handoff_status"], "ready");
    assert_eq!(packet["expected_output"], "IntentSpec JSON");
    assert_eq!(packet["validation_gate"], "task_validation_rules");
    assert!(packet["validation_rules"]
        .as_array()
        .unwrap()
        .iter()
        .any(|rule| rule["kind"] == "schema"));

    let conflict = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "task",
            "handoff",
            "--workflow",
            workflow_id,
            "--task",
            task_id,
            "--executor",
            "opencode",
            "--ttl-seconds",
            "600",
            "--budget",
            "1200",
            "--view",
            "full",
            "--output",
            "json",
        ])
        .assert()
        .failure()
        .get_output()
        .stdout
        .clone();
    let conflict_json: Value = serde_json::from_slice(&conflict).unwrap();
    assert_eq!(conflict_json["status"], "lease_conflict");
    assert_eq!(conflict_json["allowed"], false);
    assert_eq!(conflict_json["packet"]["lease_status"], "lease_conflict");
    assert_eq!(conflict_json["packet"]["handoff_ready"], true);
    assert_eq!(conflict_json["current_lease"]["executor"], "codex");
}

#[test]
fn task_handoff_fails_closed_on_executor_policy_and_leases_canonical_agy_alias() {
    let temp = tempdir().unwrap();
    let store_path = temp.path().join("foundry.sqlite");
    let planned = foundry()
        .args([
            "--store",
            store_path.to_str().unwrap(),
            "plan",
            "--goal",
            "Prove executor policy before handoff lease",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let planned_json: Value = serde_json::from_slice(&planned).unwrap();
    let workflow_id = planned_json["workflow_id"].as_str().unwrap();
    let task_id = planned_json["tasks"][0]["id"].as_str().unwrap();

    let cases = [
        ("missing", None, "executor state is missing"),
        (
            "not-installed",
            Some((false, true, true, true)),
            "installed=false",
        ),
        (
            "not-configured",
            Some((true, false, true, true)),
            "configured=false",
        ),
        (
            "not-authorized",
            Some((true, true, false, true)),
            "allowed=false",
        ),
        (
            "not-ready",
            Some((true, true, true, false)),
            "non_interactive_ready=false",
        ),
    ];
    for (case, state, expected_failure) in cases {
        if let Some((installed, configured, allowed, ready)) = state {
            persist_executor_state(&store_path, "codex", installed, configured, allowed, ready);
        }
        let output = foundry()
            .args([
                "--store",
                store_path.to_str().unwrap(),
                "task",
                "handoff",
                "--workflow",
                workflow_id,
                "--task",
                task_id,
                "--executor",
                "codex",
                "--ttl-seconds",
                "600",
                "--budget",
                "1200",
                "--view",
                "full",
                "--output",
                "json",
            ])
            .assert()
            .failure()
            .get_output()
            .stdout
            .clone();
        let json: Value = serde_json::from_slice(&output).unwrap();
        assert_eq!(
            json["status"], "handoff_blocked_executor_policy",
            "unexpected status for {case}"
        );
        assert_eq!(json["allowed"], false);
        assert_eq!(json["lease"], Value::Null);
        assert_eq!(json["packet"]["lease_status"], "not_requested");
        assert_eq!(
            json["packet"]["executor_capacity_decision"]["decision"],
            "stop"
        );
        assert_eq!(
            json["packet"]["executor_capacity_decision"]["capacity_source"],
            "executor_policy"
        );
        assert!(json["reason"].as_str().unwrap().contains(expected_failure));
        assert!(FoundryStore::open(&store_path)
            .unwrap()
            .load_task_lease(workflow_id, task_id)
            .unwrap()
            .is_none());
    }

    persist_ready_executor_state(&store_path, "agy");
    let handoff = foundry()
        .args([
            "--store",
            store_path.to_str().unwrap(),
            "task",
            "handoff",
            "--workflow",
            workflow_id,
            "--task",
            task_id,
            "--executor",
            "antigravity",
            "--ttl-seconds",
            "600",
            "--budget",
            "1200",
            "--view",
            "full",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let handoff_json: Value = serde_json::from_slice(&handoff).unwrap();
    assert_eq!(handoff_json["status"], "handoff_ready");
    assert_eq!(handoff_json["selected_executor"], "agy");
    assert_eq!(handoff_json["packet"]["selected_executor"], "agy");
    assert_eq!(handoff_json["lease"]["executor"], "agy");
}

