#[test]
fn parallel_execution_reports_concurrent_wave_metrics() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("foundry.sqlite");

    let output = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "plan",
            "--goal",
            "Build three independent features at once: feature-a, feature-b, feature-c without any sequential dependencies",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();

    let json: Value = serde_json::from_slice(&output).unwrap();
    let workflow_id = json["workflow_id"].as_str().unwrap();

    let run_output = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "run",
            "--workflow",
            workflow_id,
            "--simulate",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();

    let run: Value = serde_json::from_slice(&run_output).unwrap();
    assert_eq!(run["mode"], "simulate_parallel");
    assert!(run["concurrent_wave_count"].as_u64().unwrap() >= 1);
    assert!(run["max_concurrent_tasks"].as_u64().unwrap() >= 1);
    assert_eq!(run["status"], "completed");
    assert_eq!(
        run["runtime_security_guardrails"]["schema_version"],
        "foundry.runtime.security_guardrails.v1"
    );
    assert_eq!(
        run["runtime_security_guardrails"]["guardrails"]
            .as_array()
            .unwrap()
            .len(),
        10
    );
    assert!(
        run["cost_report"]["total_estimated_cost_usd"]
            .as_f64()
            .unwrap()
            > 0.0
    );
}

