#[test]
fn final_completion_audit_handoff_honors_explicit_large_context_budget() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("foundry.sqlite");
    persist_ready_executor_state(&store, "codex");

    let started = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "request",
            "start",
            "--goal",
            "Evoluir o Foundry CRM para expor uma web workbench operacional com pipeline, comando comercial, suporte, marketing, documentos e IA derivados do snapshot Foundry, sem estado local paralelo.",
            "--origin",
            "codex",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let started_json: Value = serde_json::from_slice(&started).unwrap();
    let workflow_id = started_json["workflow_id"].as_str().unwrap();
    set_all_task_statuses_in_stored_workflow(&store, workflow_id, "completed");
    set_workflow_status_in_stored_workflow(&store, workflow_id, "completed");

    for index in 0..24 {
        let artifact_path = temp.path().join(format!(
            "crm-operational-workbench-evidence-{index:02}-pipeline-commercial-support-marketing-documents-ai.json"
        ));
        fs::write(
            &artifact_path,
            serde_json::to_vec_pretty(&serde_json::json!({
                "schema_version": "foundry.crm_operational_workbench_evidence.v1",
                "index": index,
                "state_source": "foundry_workflow_artifacts_and_events",
                "mutation_requires_foundry": true,
                "surfaces": ["pipeline", "commercial", "support", "marketing", "documents", "ai"]
            }))
            .unwrap(),
        )
        .unwrap();
        foundry()
            .args([
                "--store",
                store.to_str().unwrap(),
                "workflow",
                "attach-artifact",
                "--workflow",
                workflow_id,
                "--path",
                artifact_path.to_str().unwrap(),
                "--kind",
                "crm_operational_workbench_snapshot",
                "--origin",
                "codex",
                "--output",
                "json",
            ])
            .assert()
            .success();
    }

    let ensured = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "request",
            "ensure-final-audit",
            "--workflow",
            workflow_id,
            "--executor",
            "codex",
            "--origin",
            "codex",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let ensured_json: Value = serde_json::from_slice(&ensured).unwrap();
    let audit_task_id = ensured_json["audit_task_id"].as_str().unwrap();
    assert_eq!(ensured_json["action"], "handoff_final_completion_audit");

    let handoff = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "task",
            "handoff",
            "--workflow",
            workflow_id,
            "--task",
            audit_task_id,
            "--executor",
            "codex",
            "--ttl-seconds",
            "600",
            "--budget",
            "12000",
            "--view",
            "full",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let handoff_json: Value = serde_json::from_slice(&handoff).unwrap();
    assert_eq!(handoff_json["status"], "handoff_ready");
    assert_eq!(handoff_json["context"]["effective_budget"], 12000);
    assert_eq!(handoff_json["context"]["handoff_ready"], true);
    assert!(
        handoff_json["context"]["replay_manifest"]["included_sections"]
            .as_array()
            .unwrap()
            .contains(&Value::String("validation_rules".to_string()))
    );
}

#[test]
fn needs_retry_response_with_rework_items_expands_into_runnable_tasks() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("foundry.sqlite");
    persist_ready_executor_state(&store, "codex");

    let started = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "request",
            "start",
            "--goal",
            "Migrate production services. Critério Final: o workflow só termina quando integration contracts and deployment evidence are verified.",
            "--origin",
            "codex",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let started_json: Value = serde_json::from_slice(&started).unwrap();
    let run_id = started_json["run_id"].as_str().unwrap();
    let workflow_id = started_json["workflow_id"].as_str().unwrap();

    set_all_task_statuses_in_stored_workflow(&store, workflow_id, "completed");
    let expected_audit_task_id =
        materialize_and_bind_final_audit_task(&store, temp.path(), run_id, workflow_id);

    let driven = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "request",
            "drive",
            "--run",
            run_id,
            "--executor",
            "codex",
            "--ttl-seconds",
            "300",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let driven_json: Value = serde_json::from_slice(&driven).unwrap();
    let audit_task_id = driven_json["handoff_task"]["task_id"].as_str().unwrap();
    assert_eq!(audit_task_id, expected_audit_task_id);
    assert_eq!(
        driven_json["handoff_task"]["title"],
        "Audit final completion criteria"
    );

    let response_path = temp.path().join("audit-needs-rework.json");
    fs::write(
        &response_path,
        serde_json::to_vec_pretty(&serde_json::json!({
            "schema_version": "foundry.executor_response.v1",
            "task_id": audit_task_id,
            "status": "needs_retry",
            "artifacts": ["artifacts/final-audit.md"],
            "trace_ref": "artifacts/final-audit.md#missing-work",
            "cost": {
                "estimated_usd": 0.0,
                "tokens_in": 0,
                "tokens_out": 0
            },
            "validation_evidence": [
                {
                    "command": "inspect final criteria",
                    "exit_code": 0,
                    "summary": "integration contracts and deployment evidence are still missing"
                }
            ],
            "rework_items": [
                {
                    "title": "Implement integration outcome contracts",
                    "goal": "Create interface lifecycle contracts with validation evidence.",
                    "context_requirements": [
                        "domain integration module",
                        "integration SDK",
                        "final audit missing criteria"
                    ],
                    "expected_output": "integration lifecycle contracts with passing validation",
                    "validation_rules": [
                        {
                            "kind": "command",
                            "command": "cargo test --all-features",
                            "expected": "tests pass"
                        }
                    ]
                },
                {
                    "title": "Prepare deployment descriptors",
                    "goal": "Create deploy descriptors or deploy_pending evidence for each service.",
                    "expected_output": "deployment evidence per service"
                }
            ]
        }))
        .unwrap(),
    )
    .unwrap();

    let validation = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "task",
            "validate-response",
            "--workflow",
            workflow_id,
            "--task",
            audit_task_id,
            "--response",
            response_path.to_str().unwrap(),
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let validation_json: Value = serde_json::from_slice(&validation).unwrap();
    assert_eq!(validation_json["status"], "accepted");
    assert_eq!(validation_json["response_status"], "needs_retry");

    let status = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "status",
            "--workflow",
            workflow_id,
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let status_json: Value = serde_json::from_slice(&status).unwrap();
    assert_eq!(status_json["tasks"].as_array().unwrap().len(), 11);
    let audit_task = status_json["tasks"]
        .as_array()
        .unwrap()
        .iter()
        .find(|task| task["id"] == audit_task_id)
        .unwrap();
    assert_eq!(audit_task["status"], "pending");
    assert_eq!(audit_task["work_item"]["backlog_state"], "rework_required");
    assert_eq!(
        audit_task["work_item"]["goal_validation"]["definitively_ready"],
        false
    );
    assert!(audit_task["work_item"]["subtasks"]
        .as_array()
        .unwrap()
        .iter()
        .all(|subtask| subtask["status"] == "pending"));
    assert!(audit_task["validation_rules"][0]["command"]
        .as_str()
        .unwrap()
        .starts_with(&format!("foundry --store {} ", store.display())));
    let generated_task = status_json["tasks"]
        .as_array()
        .unwrap()
        .iter()
        .find(|task| task["title"] == "Implement integration outcome contracts")
        .unwrap();
    assert_eq!(generated_task["status"], "pending");
    let generated_task_ids = status_json["tasks"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|task| {
            matches!(
                task["title"].as_str(),
                Some("Implement integration outcome contracts" | "Prepare deployment descriptors")
            )
        })
        .map(|task| task["id"].as_str().unwrap().to_string())
        .collect::<Vec<_>>();
    assert_eq!(generated_task_ids.len(), 2);
    for generated_task_id in &generated_task_ids {
        assert!(audit_task["dependencies"]
            .as_array()
            .unwrap()
            .contains(&Value::String(generated_task_id.clone())));
    }

    let store_handle = FoundryStore::open(&store).unwrap();
    let promotion = store_handle
        .load_workflow_events(workflow_id)
        .unwrap()
        .into_iter()
        .rev()
        .find(|event| event.kind == "executor_response_promoted")
        .unwrap();
    assert_eq!(
        promotion.data["generated_rework_task_ids"],
        serde_json::json!(generated_task_ids)
    );
    assert_eq!(promotion.data["rework_items"].as_array().unwrap().len(), 2);
    assert_eq!(
        promotion.data["rework_items"][0]["title"],
        "Implement integration outcome contracts"
    );
    for generated_task_id in &generated_task_ids {
        register_task_scoped_test_worktree(
            &store_handle,
            temp.path(),
            workflow_id,
            generated_task_id,
        );
    }

    let next = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "request",
            "drive",
            "--run",
            run_id,
            "--executor",
            "codex",
            "--ttl-seconds",
            "300",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let next_json: Value = serde_json::from_slice(&next).unwrap();
    assert_eq!(next_json["status"], "ready_for_handoff");
    assert_eq!(
        next_json["handoff_task"]["title"],
        "Implement integration outcome contracts"
    );
    assert_foundry_store_prefix(&next_json["next_command"], &store);
}

#[test]
fn improve_candidates_prioritize_generated_rework_tasks_without_driveable_run() {
    use foundry_core::graph::{self, ExecutorKind};

    let temp = tempdir().unwrap();
    let store_path = temp.path().join("foundry.sqlite");
    let store = FoundryStore::open(&store_path).unwrap();
    let mut workflow = graph::create_workflow(foundry_core::intent::parse_intent(
        "Deliver final workflow result with a final report and audited delivery evidence.",
    ));
    workflow.status = "running".to_string();
    workflow.tasks = vec![graph::task(
        "task-audit",
        "Audit final completion criteria",
        &[],
        &[],
        vec![],
        "final_completion_audit JSON",
        (ExecutorKind::Ai, 0.35),
    )];
    let workflow_id = workflow.id.clone();
    store.save_workflow(&workflow).unwrap();
    drop(store);

    let response_path = temp.path().join("needs-rework.json");
    fs::write(
        &response_path,
        serde_json::to_vec_pretty(&serde_json::json!({
            "schema_version": "foundry.executor_response.v1",
            "task_id": "task-audit",
            "status": "needs_retry",
            "artifacts": ["artifacts/final-audit.md"],
            "trace_ref": "artifacts/final-audit.md#missing-work",
            "cost": {
                "estimated_usd": 0.0,
                "tokens_in": 0,
                "tokens_out": 0
            },
            "validation_evidence": [
                {
                    "command": "inspect final outcome",
                    "exit_code": 0,
                    "summary": "final delivery evidence is still missing"
                }
            ],
            "rework_items": [
                {
                    "title": "Produce final delivery evidence",
                    "goal": "Attach final report and delivery evidence before final completion.",
                    "expected_output": "final delivery evidence artifact"
                }
            ]
        }))
        .unwrap(),
    )
    .unwrap();

    foundry()
        .args([
            "--store",
            store_path.to_str().unwrap(),
            "task",
            "validate-response",
            "--workflow",
            &workflow_id,
            "--task",
            "task-audit",
            "--response",
            response_path.to_str().unwrap(),
            "--output",
            "json",
        ])
        .assert()
        .success();

    let persisted_store = FoundryStore::open(&store_path).unwrap();
    let persisted_workflow = persisted_store.load_workflow(&workflow_id).unwrap();
    let original_task = persisted_workflow
        .tasks
        .iter()
        .find(|task| task.id == "task-audit")
        .unwrap();
    assert_eq!(
        original_task.status,
        foundry_core::graph::TaskStatus::Pending
    );
    assert_eq!(original_task.work_item.backlog_state, "rework_required");
    assert!(!original_task.work_item.goal_validation.definitively_ready);
    assert!(original_task.dependencies.contains(&"task-002".to_string()));
    assert_eq!(
        persisted_workflow.tasks[1].status,
        foundry_core::graph::TaskStatus::Pending
    );
    drop(persisted_store);

    let output = foundry()
        .args([
            "--store",
            store_path.to_str().unwrap(),
            "improve",
            "candidates",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let report: Value = serde_json::from_slice(&output).unwrap();
    let top = &report["candidates"][0];
    assert_eq!(top["workflow_id"], workflow_id);
    assert_eq!(top["recommended_action"], "run_rework_loop");
    assert!(top["reasons"]
        .as_array()
        .unwrap()
        .iter()
        .any(|reason| reason["code"] == "rework_loop_signal"));
    assert_eq!(
        top["suggested_commands"][0],
        serde_json::json!([
            "foundry",
            "task",
            "handoff",
            "--workflow",
            workflow_id,
            "--task",
            "task-002",
            "--executor",
            "codex",
            "--view",
            "compact",
            "--output",
            "json"
        ])
    );
}

#[test]
fn request_switch_executor_hot_swaps_agent_without_stopping_run_or_losing_directives() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("foundry.sqlite");

    let started = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "request",
            "start",
            "--goal",
            "Implement SDK because the user explicitly requested it",
            "--origin",
            "codex",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();

    let started_json: Value = serde_json::from_slice(&started).unwrap();
    let run_id = started_json["run_id"].as_str().unwrap();
    let workflow_id = started_json["workflow_id"].as_str().unwrap();
    assert_eq!(
        started_json["handoff_contract"]["policy"]["user_directives_remain_authoritative"],
        true
    );
    assert_eq!(
        started_json["handoff_contract"]["policy"]["executor_hot_swap_supported"],
        true
    );
    assert!(started_json["handoff_contract"]["validation_rules"]
        .as_array()
        .unwrap()
        .contains(&serde_json::json!(
            "explicit-user-directives-outrank-autonomous-executor-preferences"
        )));

    foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "request",
            "heartbeat",
            "--run",
            run_id,
            "--executor",
            "codex",
            "--summary",
            "codex is close to limit but workflow remains active",
            "--ttl-seconds",
            "600",
            "--origin",
            "codex",
            "--output",
            "json",
        ])
        .assert()
        .success();

    let switched = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "request",
            "switch-executor",
            "--run",
            run_id,
            "--executor",
            "opencode",
            "--fallback-executor",
            "codex",
            "--fallback-executor",
            "opencode",
            "--summary",
            "opencode takes over from persisted Foundry state",
            "--reason",
            "codex model limit approaching",
            "--ttl-seconds",
            "900",
            "--origin",
            "codex",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();

    let switched_json: Value = serde_json::from_slice(&switched).unwrap();
    assert_eq!(
        switched_json["schema_version"],
        "foundry.request_executor_switch.v1"
    );
    assert_eq!(switched_json["status"], "running");
    assert_eq!(switched_json["run_id"], run_id);
    assert_eq!(switched_json["workflow_id"], workflow_id);
    assert_eq!(switched_json["previous_status"], "running");
    assert_eq!(switched_json["previous_executor"], "codex");
    assert_eq!(switched_json["new_executor"], "opencode");
    assert_eq!(
        switched_json["brain_switch_policy"]["schema_version"],
        "foundry.brain_switch_policy.v1"
    );
    assert_eq!(
        switched_json["brain_switch_policy"]["orchestrator_brain"],
        "foundry"
    );
    assert_eq!(
        switched_json["brain_switch_policy"]["switch_scope"],
        "workflow_run_execution_brain"
    );
    assert_eq!(
        switched_json["brain_switch_policy"]["can_switch_without_stopping_workflow"],
        true
    );
    assert_eq!(
        switched_json["brain_switch_policy"]["preserves_run_id"],
        true
    );
    assert_eq!(
        switched_json["brain_switch_policy"]["preserves_workflow_id"],
        true
    );
    assert_eq!(
        switched_json["brain_switch_policy"]["preserves_checkpoints"],
        true
    );
    assert_eq!(
        switched_json["brain_switch_policy"]["node_brain_routing_source"],
        "workflow.tasks[].node_brain_routing"
    );
    assert!(
        switched_json["brain_switch_policy"]["node_brain_routing_mutation_command"]
            .as_array()
            .unwrap()
            .contains(&serde_json::json!("update-node-brain"))
    );
    assert_eq!(
        switched_json["fallback_executors"],
        serde_json::json!(["codex"])
    );
    assert_eq!(switched_json["activity"]["executor"], "opencode");
    assert_eq!(switched_json["activity"]["heartbeat_status"], "fresh");
    assert_eq!(switched_json["executor_switch"]["from_executor"], "codex");
    assert_eq!(switched_json["executor_switch"]["to_executor"], "opencode");
    assert_eq!(
        switched_json["executor_switch"]["fallback_executors"],
        serde_json::json!(["codex"])
    );
    assert_eq!(
        switched_json["executor_switch"]["reason"],
        "codex model limit approaching"
    );
    assert_eq!(
        switched_json["executor_switch"]["continuity_policy"]["preserve_run_id"],
        true
    );
    assert_eq!(
        switched_json["executor_switch"]["continuity_policy"]["preserve_workflow_id"],
        true
    );
    assert_eq!(
        switched_json["executor_switch"]["continuity_policy"]["preserve_checkpoints"],
        true
    );
    assert_eq!(
        switched_json["executor_switch"]["continuity_policy"]["old_executor_shutdown_required"],
        false
    );
    assert_eq!(
        switched_json["executor_switch"]["continuity_policy"]
            ["user_directives_remain_authoritative"],
        true
    );

    let status = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "request",
            "status",
            "--run",
            run_id,
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let status_json: Value = serde_json::from_slice(&status).unwrap();
    assert_eq!(status_json["status"], "running");
    assert_eq!(status_json["activity"]["executor"], "opencode");
    assert_eq!(
        status_json["executor_fallbacks"],
        serde_json::json!(["codex"])
    );
    assert_eq!(status_json["executor_switch_count"], 1);
    assert_eq!(
        status_json["latest_executor_switch"]["to_executor"],
        "opencode"
    );
    assert_eq!(
        status_json["latest_executor_switch"]["continuity_policy"]
            ["user_directives_remain_authoritative"],
        true
    );
}

