fn request_cancel_with_mcp_tool_works_through_mcp_protocol() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("foundry.sqlite");

    let started = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "request",
            "start",
            "--goal",
            "Cancel through MCP test",
            "--origin",
            "codex",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let started_json: Value = serde_json::from_slice(&started).unwrap();
    let run_id = started_json["run_id"].as_str().unwrap();

    foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "mcp",
            "call",
            "foundry.request.cancel",
            "--input",
            &format!(r#"{{"run_id":"{}","origin":"mcp"}}"#, run_id),
            "--output",
            "json",
        ])
        .assert()
        .success();
}

