#[test]
fn interactive_slash_command_catalog_is_discoverable_and_scriptable() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("foundry.sqlite");

    let output = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "interactive",
            "slash-commands",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();

    let json: Value = serde_json::from_slice(&output).unwrap();
    assert_eq!(json["status"], "slash_commands_loaded");
    assert_eq!(
        json["schema_version"],
        "foundry.interactive.slash_commands.v1"
    );
    for name in [
        "/help",
        "/status",
        "/list",
        "/inspect",
        "/runs",
        "/workflows",
        "/ui-composition",
        "/artifacts",
        "/task-board",
        "/costs",
        "/improvement-loop",
        "/config",
        "/sync",
        "/executors",
        "/brains",
        "/sessions",
        "/sessions history",
        "/sessions lifecycle",
        "/actions",
        "/action",
        "/shells",
        "/harness",
        "/harness doctor",
        "/harness headroom-plan",
        "/harness headroom-stats",
        "/harness adoption-plan",
        "/harness bootstrap",
        "/runtimes",
        "/validate",
        "/approve",
        "/reject",
        "/goal",
        "/attach",
        "/resume",
        "/pause",
        "/stop",
        "/delete",
        "/export",
        "/logs",
        "/update",
        "/workers",
        "/context-memory",
        "/operating-context",
        "/context",
        "/handoff",
        "/pm",
        "/decision",
        "/exit",
        "/quit",
    ] {
        let command = find_slash_command(&json, name);
        assert_eq!(command["name"], name);
        assert_eq!(command["scriptable"], true);
        if name == "/exit" || name == "/quit" {
            assert!(
                command["equivalent_command"].as_array().unwrap().is_empty(),
                "/exit and /quit are REPL-only and should have no equivalent foundry command"
            );
        } else {
            assert!(
                command["equivalent_command"].as_array().unwrap().len() >= 2,
                "{name} should have at least 2 equivalent commands"
            );
        }
    }

    let status = find_slash_command(&json, "/status");
    assert_eq!(status["risk_level"], "low");
    assert_eq!(status["mutates_workflow"], false);
    assert!(status["equivalent_command"]
        .as_array()
        .unwrap()
        .contains(&Value::String("status".to_string())));

    let context = find_slash_command(&json, "/context");
    assert_eq!(context["risk_level"], "low");
    assert_eq!(context["mutates_workflow"], false);
    assert!(context["equivalent_command"]
        .as_array()
        .unwrap()
        .contains(&Value::String("context".to_string())));

    let improvement_loop = find_slash_command(&json, "/improvement-loop");
    assert_eq!(improvement_loop["risk_level"], "low");
    assert_eq!(improvement_loop["mutates_workflow"], false);
    assert!(improvement_loop["equivalent_command"]
        .as_array()
        .unwrap()
        .contains(&Value::String("improvement-loop".to_string())));

    let context_memory = find_slash_command(&json, "/context-memory");
    assert_eq!(context_memory["risk_level"], "low");
    assert_eq!(context_memory["mutates_workflow"], false);
    assert!(context_memory["equivalent_command"]
        .as_array()
        .unwrap()
        .contains(&Value::String("context-memory".to_string())));

    let operating_context = find_slash_command(&json, "/operating-context");
    assert_eq!(operating_context["risk_level"], "low");
    assert_eq!(operating_context["mutates_workflow"], false);
    assert!(operating_context["equivalent_command"]
        .as_array()
        .unwrap()
        .contains(&Value::String("operating-context".to_string())));

    let handoff = find_slash_command(&json, "/handoff");
    assert_eq!(handoff["risk_level"], "medium");
    assert_eq!(handoff["mutates_workflow"], true);
    assert!(handoff["equivalent_command"]
        .as_array()
        .unwrap()
        .contains(&Value::String("handoff".to_string())));

    let harness_doctor = find_slash_command(&json, "/harness doctor");
    assert_eq!(harness_doctor["risk_level"], "low");
    assert_eq!(harness_doctor["mutates_workflow"], false);
    assert!(harness_doctor["equivalent_command"]
        .as_array()
        .unwrap()
        .contains(&Value::String("doctor".to_string())));
    assert!(harness_doctor["equivalent_command"]
        .as_array()
        .unwrap()
        .contains(&Value::String("<executor>".to_string())));

    let headroom_plan = find_slash_command(&json, "/harness headroom-plan");
    assert_eq!(headroom_plan["risk_level"], "low");
    assert_eq!(headroom_plan["mutates_workflow"], false);
    assert!(headroom_plan["equivalent_command"]
        .as_array()
        .unwrap()
        .contains(&Value::String("headroom-plan".to_string())));
    assert!(headroom_plan["equivalent_command"]
        .as_array()
        .unwrap()
        .contains(&Value::String("<executor>".to_string())));

    let headroom_stats = find_slash_command(&json, "/harness headroom-stats");
    assert_eq!(headroom_stats["risk_level"], "low");
    assert_eq!(headroom_stats["mutates_workflow"], false);
    assert!(headroom_stats["equivalent_command"]
        .as_array()
        .unwrap()
        .contains(&Value::String("headroom-stats".to_string())));

    let adoption_plan = find_slash_command(&json, "/harness adoption-plan");
    assert_eq!(adoption_plan["risk_level"], "low");
    assert_eq!(adoption_plan["mutates_workflow"], false);
    assert!(adoption_plan["equivalent_command"]
        .as_array()
        .unwrap()
        .contains(&Value::String("adoption-plan".to_string())));
    assert!(adoption_plan["equivalent_command"]
        .as_array()
        .unwrap()
        .contains(&Value::String("<executor>".to_string())));
    assert!(adoption_plan["equivalent_command"]
        .as_array()
        .unwrap()
        .contains(&Value::String("<dir>".to_string())));

    let bootstrap = find_slash_command(&json, "/harness bootstrap");
    assert_eq!(bootstrap["risk_level"], "medium");
    assert_eq!(bootstrap["mutates_workflow"], true);
    assert!(bootstrap["equivalent_command"]
        .as_array()
        .unwrap()
        .contains(&Value::String("bootstrap".to_string())));
    assert!(bootstrap["equivalent_command"]
        .as_array()
        .unwrap()
        .contains(&Value::String("--apply".to_string())));
    assert!(bootstrap["equivalent_command"]
        .as_array()
        .unwrap()
        .contains(&Value::String("<operator>".to_string())));

    let pm = find_slash_command(&json, "/pm");
    assert_eq!(pm["risk_level"], "medium");
    assert_eq!(pm["mutates_workflow"], true);
    assert!(pm["equivalent_command"]
        .as_array()
        .unwrap()
        .contains(&Value::String("interactive".to_string())));

    let decision = find_slash_command(&json, "/decision");
    assert_eq!(decision["risk_level"], "medium");
    assert_eq!(decision["mutates_workflow"], true);
    assert!(decision["equivalent_command"]
        .as_array()
        .unwrap()
        .contains(&Value::String("decision".to_string())));
}

#[test]
fn interactive_route_treats_exit_aliases_as_local_commands_without_workflow() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("foundry.sqlite");

    for input in ["q", "quit", "exit", "/quit", "/exit"] {
        let output = foundry()
            .args([
                "--store",
                store.to_str().unwrap(),
                "interactive",
                "route",
                "--input",
                input,
                "--origin",
                "codex",
                "--output",
                "json",
            ])
            .assert()
            .success()
            .get_output()
            .stdout
            .clone();
        let json: Value = serde_json::from_slice(&output).unwrap();

        assert_eq!(json["status"], "routed");
        assert_eq!(json["input_kind"], "local_command");
        assert_eq!(json["routing_decision"], "exit_repl");
        assert_eq!(json["workflow_created"], false);
        assert_eq!(json["run_id"], Value::Null);
        assert_eq!(json["workflow_id"], Value::Null);
        assert_eq!(json["slash_command"]["recognized"], true);
        assert_eq!(json["slash_command"]["mutates_workflow"], false);
        assert_eq!(
            json["slash_command"]["execution_boundary"],
            "local_repl_exit_not_executed_by_foundry"
        );
        assert_eq!(json["retention_decision"]["action"], "none");
    }
}

#[test]
fn interactive_action_slash_commands_route_to_registry_and_invocation() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("foundry.sqlite");

    let catalog_output = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "interactive",
            "slash-commands",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let catalog: Value = serde_json::from_slice(&catalog_output).unwrap();

    let actions = find_slash_command(&catalog, "/actions");
    assert_eq!(actions["risk_level"], "low");
    assert_eq!(actions["mutates_workflow"], false);
    assert!(actions["equivalent_command"]
        .as_array()
        .unwrap()
        .contains(&Value::String("action-registry".to_string())));

    let action = find_slash_command(&catalog, "/action");
    assert_eq!(action["risk_level"], "low");
    assert_eq!(action["mutates_workflow"], false);
    assert!(action["equivalent_command"]
        .as_array()
        .unwrap()
        .contains(&Value::String("action-invocation".to_string())));
    assert!(action["equivalent_command"]
        .as_array()
        .unwrap()
        .contains(&Value::String("<action-id>".to_string())));

    let route_output = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "interactive",
            "route",
            "--input",
            "/action patch.diff",
            "--origin",
            "codex",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let route: Value = serde_json::from_slice(&route_output).unwrap();
    assert_eq!(route["input_kind"], "slash_command");
    assert_eq!(route["routing_decision"], "slash_command");
    assert_eq!(route["workflow_created"], false);
    assert_eq!(route["slash_command"]["name"], "/action");
    assert_eq!(route["slash_command"]["recognized"], true);
    assert_eq!(route["slash_command"]["mutates_workflow"], false);
    assert!(route["slash_command"]["equivalent_command"]
        .as_array()
        .unwrap()
        .contains(&Value::String("action-invocation".to_string())));
}

#[test]
fn interactive_route_answers_simple_question_without_creating_workflow_state() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("foundry.sqlite");

    let output = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "interactive",
            "route",
            "--input",
            "What is the current Foundry status?",
            "--origin",
            "codex",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();

    let json: Value = serde_json::from_slice(&output).unwrap();
    assert_eq!(json["status"], "routed");
    assert_eq!(json["input_kind"], "chat");
    assert_eq!(json["routing_decision"], "direct_answer");
    assert_eq!(json["workflow_created"], false);
    assert_eq!(json["run_id"], Value::Null);
    assert_eq!(json["workflow_id"], Value::Null);
    let answer = json["answer"].as_str().unwrap();
    assert_ne!(answer, "não sei");
    assert!(answer.to_ascii_lowercase().contains("foundry"));
    assert_eq!(json["retention_decision"]["action"], "none");

    let listed = foundry()
        .args([
            "--store",
            store.to_str().unwrap(),
            "list",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let listed_json: Value = serde_json::from_slice(&listed).unwrap();
    assert_eq!(listed_json["summary"]["total"], 0);
}

